"use client";

import React, { useState, useEffect } from 'react';
import { useLanguage } from '@/lib/language-context';
import { apiRequest } from '@/lib/api';
import {
  Calculator,
  IndianRupee,
  Truck,
  Layers,
  ArrowRight,
  TrendingUp,
  MapPin,
  RefreshCw,
  AlertCircle,
  HelpCircle,
  Sliders,
  DollarSign,
  PieChart,
  Percent,
  Warehouse,
  ShieldCheck
} from 'lucide-react';

interface MandiOption {
  id: string;
  name: string;
  state: string;
  district: string;
  latitude: number;
  longitude: number;
}

interface CommodityOption {
  id: string;
  code: string;
  name_en: string;
  name_hi: string;
  name_mr: string;
  standard_unit: string;
}

interface ProfitComparisonItem {
  market_id: string;
  market_name: string;
  distance_km: number;
  modal_price: number;
  gross_revenue: number;
  transport_cost: number;
  net_realization: number;
  net_realization_per_quintal: number;
  is_current_selection: boolean;
}

interface ProfitCalculationResult {
  quantity_entered: number;
  quantity_unit: string;
  quantity_quintals: number;
  market_name: string;
  distance_km: number;
  mandi_price_per_quintal: number;
  gross_revenue: number;
  transport_cost: number;
  handling_cost: number;
  market_cess: number;
  storage_cost: number;
  spoilage_loss: number;
  total_expenses: number;
  net_realization: number;
  net_realization_per_quintal: number;
  profit_margin_pct: number;
  mandi_comparisons: ProfitComparisonItem[];
}

export default function CalculatorPage() {
  const { language, t } = useLanguage();

  const [commodities, setCommodities] = useState<CommodityOption[]>([]);
  const [selectedCommodityId, setSelectedCommodityId] = useState<string>('c0010000-0000-0000-0000-000000000001'); // Onion
  const [quantity, setQuantity] = useState<number>(50);
  const [unit, setUnit] = useState<'QUINTAL' | 'KG' | 'TONNE'>('QUINTAL');

  // Logistics parameters
  const [distanceKm, setDistanceKm] = useState<number>(35.0);
  const [transportRate, setTransportRate] = useState<number>(0.75); // ₹/km/q
  const [handlingRate, setHandlingRate] = useState<number>(15.0); // ₹/q
  const [marketFeePct, setMarketFeePct] = useState<number>(1.5); // 1.5%

  // Storage parameters
  const [storageDays, setStorageDays] = useState<number>(0);
  const [storageRatePerDay, setStorageRatePerDay] = useState<number>(1.20);
  const [spoilageRatePct, setSpoilageRatePct] = useState<number>(0.15);

  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<ProfitCalculationResult | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Load commodities
  useEffect(() => {
    async function loadCommodities() {
      try {
        const res = await apiRequest<CommodityOption[]>('/markets/commodities');
        setCommodities(res);
      } catch (err) {
        console.error('Failed to load commodities:', err);
      }
    }
    loadCommodities();
  }, []);

  // Compute profit
  const calculateProfit = async () => {
    setLoading(true);
    setErrorMsg(null);
    try {
      const res = await apiRequest<ProfitCalculationResult>('/calculator/profit', {
        method: 'POST',
        body: JSON.stringify({
          commodity_id: selectedCommodityId,
          quantity: quantity,
          unit: unit,
          distance_km: distanceKm,
          transport_rate_per_km_quintal: transportRate,
          handling_cost_per_quintal: handlingRate,
          market_fee_pct: marketFeePct / 100.0,
          storage_days: storageDays,
          daily_storage_cost_per_quintal: storageRatePerDay,
          daily_spoilage_rate_pct: spoilageRatePct / 100.0,
        }),
      });
      setResult(res);
    } catch (err: any) {
      console.error('Calculation error:', err);
      setErrorMsg(t('noDataAvailable'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    calculateProfit();
  }, [selectedCommodityId, quantity, unit, distanceKm, transportRate, handlingRate, marketFeePct, storageDays]);

  const getCommodityName = (c: CommodityOption) => {
    if (language === 'hi') return c.name_hi;
    if (language === 'mr') return c.name_mr;
    return c.name_en;
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto space-y-8">

        {/* Header */}
        <div className="border-b border-slate-200 dark:border-slate-800 pb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-semibold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-300/40 mb-2">
              <Calculator className="w-3.5 h-3.5" />
              <span>{t('calculator')} • Net Realization Model</span>
            </div>
            <h1 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">
              {language === 'hi' ? 'मंडी शुद्ध लाभ एवं खर्च कैलकुलेटर' : language === 'mr' ? 'मंडी निव्वळ नफा व खर्च कॅल्क्युलेटर' : 'Mandi Net Selling Realization Calculator'}
            </h1>
            <p className="mt-1 text-slate-600 dark:text-slate-400 text-sm max-w-2xl">
              {language === 'hi'
                ? 'परिवहन दूरी, श्रमिक मजदूरी, मंडी सेस व भंडारण लागत घटाकर वास्तविक हाथ में आने वाली राशि जानिए।'
                : language === 'mr'
                ? 'वाहतूक भाडे, हमाली, बाजार उपकर व साठवणूक नुकसान वजा करून शेतकऱ्याच्या हातात पडणारा खरा नफा.'
                : 'Calculate your actual take-home revenue after accounting for freight distance, APMC fees, loading charges, and holding losses.'}
            </p>
          </div>

          <button
            onClick={calculateProfit}
            disabled={loading}
            className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-medium shadow-sm transition disabled:opacity-50 cursor-pointer self-start md:self-auto"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            <span>Recalculate</span>
          </button>
        </div>

        {/* Interactive Calculator Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Controls Column (5 cols) */}
          <div className="lg:col-span-5 space-y-6">

            {/* Harvest Volume Card */}
            <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
              <h2 className="text-sm font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 flex items-center gap-2">
                <Sliders className="w-4 h-4 text-emerald-500" />
                <span>Crop & Harvest Volume</span>
              </h2>

              <div>
                <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                  {language === 'hi' ? 'फसल' : language === 'mr' ? 'पीक' : 'Crop'}
                </label>
                <select
                  value={selectedCommodityId}
                  onChange={(e) => setSelectedCommodityId(e.target.value)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-sm outline-none focus:ring-2 focus:ring-emerald-500"
                >
                  {commodities.map((c) => (
                    <option key={c.id} value={c.id}>
                      {getCommodityName(c)}
                    </option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                    {language === 'hi' ? 'मात्रा' : language === 'mr' ? 'प्रमाण' : 'Quantity'}
                  </label>
                  <input
                    type="number"
                    min="1"
                    value={quantity}
                    onChange={(e) => setQuantity(Math.max(1, parseFloat(e.target.value) || 0))}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-sm outline-none focus:ring-2 focus:ring-emerald-500"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                    {language === 'hi' ? 'इकाई' : language === 'mr' ? 'एकक' : 'Unit'}
                  </label>
                  <select
                    value={unit}
                    onChange={(e) => setUnit(e.target.value as any)}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-sm outline-none focus:ring-2 focus:ring-emerald-500"
                  >
                    <option value="QUINTAL">Quintal (100 Kg)</option>
                    <option value="KG">Kilogram (Kg)</option>
                    <option value="TONNE">Metric Tonne (1,000 Kg)</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Logistics & Transit Expenses Card */}
            <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
              <h2 className="text-sm font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 flex items-center gap-2">
                <Truck className="w-4 h-4 text-emerald-500" />
                <span>Logistics & Mandi Expenses</span>
              </h2>

              <div>
                <div className="flex justify-between text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                  <span>Mandi Transit Distance</span>
                  <span className="font-bold text-emerald-600 dark:text-emerald-400">{distanceKm} km</span>
                </div>
                <input
                  type="range"
                  min="5"
                  max="250"
                  step="5"
                  value={distanceKm}
                  onChange={(e) => setDistanceKm(parseFloat(e.target.value))}
                  className="w-full accent-emerald-600"
                />
              </div>

              <div className="grid grid-cols-2 gap-3 pt-2">
                <div>
                  <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Transport (₹/km/q)
                  </label>
                  <input
                    type="number"
                    step="0.05"
                    value={transportRate}
                    onChange={(e) => setTransportRate(parseFloat(e.target.value) || 0)}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-xs outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                    Handling/Labor (₹/q)
                  </label>
                  <input
                    type="number"
                    step="1"
                    value={handlingRate}
                    onChange={(e) => setHandlingRate(parseFloat(e.target.value) || 0)}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-xs outline-none"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                  APMC Market Cess / Fee (%)
                </label>
                <input
                  type="number"
                  step="0.1"
                  value={marketFeePct}
                  onChange={(e) => setMarketFeePct(parseFloat(e.target.value) || 0)}
                  className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-xs outline-none"
                />
              </div>
            </div>

            {/* Storage & Holding Cost Card */}
            <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
              <h2 className="text-sm font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 flex items-center gap-2">
                <Warehouse className="w-4 h-4 text-emerald-500" />
                <span>Holding / Storage Duration</span>
              </h2>

              <div>
                <div className="flex justify-between text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                  <span>Holding Time</span>
                  <span className="font-bold text-emerald-600 dark:text-emerald-400">{storageDays} Days</span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="45"
                  step="1"
                  value={storageDays}
                  onChange={(e) => setStorageDays(parseInt(e.target.value) || 0)}
                  className="w-full accent-emerald-600"
                />
              </div>

              {storageDays > 0 && (
                <div className="grid grid-cols-2 gap-3 pt-1 text-xs">
                  <div>
                    <span className="text-slate-500">Storage Fee:</span>
                    <div className="font-medium text-slate-900 dark:text-white">₹{storageRatePerDay}/q/day</div>
                  </div>
                  <div>
                    <span className="text-slate-500">Est. Daily Spoilage:</span>
                    <div className="font-medium text-amber-600">{spoilageRatePct}% / day</div>
                  </div>
                </div>
              )}
            </div>

          </div>

          {/* Results Column (7 cols) */}
          <div className="lg:col-span-7 space-y-6">

            {result ? (
              <>
                {/* Big Net Realization Result Box */}
                <div className="bg-gradient-to-br from-emerald-600 to-green-700 rounded-3xl p-6 sm:p-8 text-white shadow-xl">
                  <div className="flex items-center justify-between text-emerald-100 text-xs font-semibold uppercase tracking-wider mb-2">
                    <span>{t('netRealization')}</span>
                    <span>{result.market_name}</span>
                  </div>

                  <div className="text-4xl sm:text-5xl font-extrabold tracking-tight">
                    ₹{result.net_realization.toLocaleString('en-IN', { maximumFractionDigits: 0 })}
                  </div>

                  <div className="mt-2 text-emerald-100 text-sm font-medium flex items-center gap-4">
                    <span><strong>₹{result.net_realization_per_quintal.toFixed(1)}</strong> / Quintal in-pocket</span>
                    <span>•</span>
                    <span>Realized Margin: <strong>{result.profit_margin_pct.toFixed(1)}%</strong></span>
                  </div>

                  <div className="mt-6 pt-6 border-t border-emerald-500/40 grid grid-cols-3 gap-4 text-center">
                    <div className="bg-white/10 rounded-xl p-3">
                      <div className="text-[11px] text-emerald-200 uppercase font-medium">{t('grossRevenue')}</div>
                      <div className="text-lg font-bold mt-0.5">₹{result.gross_revenue.toLocaleString('en-IN')}</div>
                    </div>
                    <div className="bg-white/10 rounded-xl p-3">
                      <div className="text-[11px] text-emerald-200 uppercase font-medium">Total Expenses</div>
                      <div className="text-lg font-bold mt-0.5 text-rose-200">-₹{result.total_expenses.toLocaleString('en-IN')}</div>
                    </div>
                    <div className="bg-white/10 rounded-xl p-3">
                      <div className="text-[11px] text-emerald-200 uppercase font-medium">Mandi Price</div>
                      <div className="text-lg font-bold mt-0.5">₹{result.mandi_price_per_quintal}/q</div>
                    </div>
                  </div>
                </div>

                {/* Itemized Expense Breakdown */}
                <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
                  <h3 className="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <PieChart className="w-5 h-5 text-emerald-500" />
                    <span>Itemized Deductions Breakdown</span>
                  </h3>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
                    <div className="p-3.5 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-100 dark:border-slate-800 flex justify-between items-center">
                      <div className="flex items-center gap-2 text-slate-700 dark:text-slate-300 text-xs">
                        <Truck className="w-4 h-4 text-emerald-500" />
                        <span>Transport Freight ({result.distance_km} km)</span>
                      </div>
                      <span className="font-bold text-rose-600 dark:text-rose-400">
                        ₹{result.transport_cost.toLocaleString('en-IN')}
                      </span>
                    </div>

                    <div className="p-3.5 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-100 dark:border-slate-800 flex justify-between items-center">
                      <div className="flex items-center gap-2 text-slate-700 dark:text-slate-300 text-xs">
                        <Layers className="w-4 h-4 text-emerald-500" />
                        <span>Handling & Labor</span>
                      </div>
                      <span className="font-bold text-rose-600 dark:text-rose-400">
                        ₹{result.handling_cost.toLocaleString('en-IN')}
                      </span>
                    </div>

                    <div className="p-3.5 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-100 dark:border-slate-800 flex justify-between items-center">
                      <div className="flex items-center gap-2 text-slate-700 dark:text-slate-300 text-xs">
                        <Percent className="w-4 h-4 text-emerald-500" />
                        <span>APMC Market Cess</span>
                      </div>
                      <span className="font-bold text-rose-600 dark:text-rose-400">
                        ₹{result.market_cess.toLocaleString('en-IN')}
                      </span>
                    </div>

                    <div className="p-3.5 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-100 dark:border-slate-800 flex justify-between items-center">
                      <div className="flex items-center gap-2 text-slate-700 dark:text-slate-300 text-xs">
                        <Warehouse className="w-4 h-4 text-emerald-500" />
                        <span>Holding & Spoilage Loss</span>
                      </div>
                      <span className="font-bold text-rose-600 dark:text-rose-400">
                        ₹{(result.storage_cost + result.spoilage_loss).toLocaleString('en-IN')}
                      </span>
                    </div>
                  </div>
                </div>

                {/* Multi-Mandi Comparison Table */}
                {result.mandi_comparisons && result.mandi_comparisons.length > 0 && (
                  <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
                    <h3 className="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">
                      <MapPin className="w-5 h-5 text-emerald-500" />
                      <span>Alternative Mandis Net Realization</span>
                    </h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400">
                      Compare your net realization at other reachable mandis after adjusting for their specific distances
                    </p>

                    <div className="overflow-x-auto">
                      <table className="w-full text-left text-xs">
                        <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 uppercase font-semibold">
                          <tr>
                            <th className="py-2.5 px-3">Mandi</th>
                            <th className="py-2.5 px-3">Distance</th>
                            <th className="py-2.5 px-3">Modal Rate</th>
                            <th className="py-2.5 px-3">Freight</th>
                            <th className="py-2.5 px-3 font-bold text-emerald-600 dark:text-emerald-400">Net Take-Home</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                          {result.mandi_comparisons.map((c) => (
                            <tr key={c.market_id} className="hover:bg-slate-50 dark:hover:bg-slate-800/40">
                              <td className="py-3 px-3 font-semibold text-slate-900 dark:text-white">
                                {c.market_name}
                              </td>
                              <td className="py-3 px-3 text-slate-600 dark:text-slate-400">
                                {c.distance_km} km
                              </td>
                              <td className="py-3 px-3 font-medium text-slate-900 dark:text-white">
                                ₹{c.modal_price}
                              </td>
                              <td className="py-3 px-3 text-rose-600 dark:text-rose-400">
                                -₹{c.transport_cost.toLocaleString('en-IN')}
                              </td>
                              <td className="py-3 px-3 font-extrabold text-emerald-600 dark:text-emerald-400">
                                ₹{c.net_realization.toLocaleString('en-IN')}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}

              </>
            ) : (
              <div className="h-64 flex flex-col items-center justify-center bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 text-slate-400">
                <Calculator className="w-10 h-10 mb-2 opacity-40" />
                <p className="text-sm">Enter harvest parameters to calculate net profit</p>
              </div>
            )}

          </div>

        </div>

      </div>
    </div>
  );
}

