"use client";

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/lib/auth-context';
import { useLanguage } from '@/lib/language-context';
import { apiRequest } from '@/lib/api';
import {
  Sprout,
  Plus,
  Trash2,
  Edit3,
  Calendar,
  Layers,
  MapPin,
  CheckCircle2,
  AlertCircle,
  X,
  Filter,
  TrendingUp,
  Tag,
  ArrowRight
} from 'lucide-react';

interface Crop {
  id: string;
  crop_code: string;
  farmer_id: string;
  farm_location?: string;
  crop_name: string;
  variety?: string;
  acreage: number;
  quantity: number;
  quantity_unit: string;
  sowing_date: string;
  expected_harvest_date: string;
  actual_harvest_date?: string;
  status: 'Growing' | 'Ready to Harvest' | 'Stored' | 'Partially Sold' | 'Completed';
  notes?: string;
  aliases: Record<string, string>;
  created_at: string;
  updated_at: string;
}

export default function CropsPage() {
  const { user, profile, loginDemo } = useAuth();
  const { language, t } = useLanguage();

  const [crops, setCrops] = useState<Crop[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedStatus, setSelectedStatus] = useState<string>('ALL');

  // Modal states
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCrop, setEditingCrop] = useState<Crop | null>(null);
  const [deleteConfirmationId, setDeleteConfirmationId] = useState<string | null>(null);
  const [notification, setNotification] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  // Form states
  const [cropName, setCropName] = useState('Onion');
  const [variety, setVariety] = useState('Nashik Red (गरवा कांदा)');
  const [farmLocation, setFarmLocation] = useState('Lasalgaon, Nashik, Maharashtra');
  const [acreage, setAcreage] = useState(2.5);
  const [quantity, setQuantity] = useState(85.0);
  const [quantityUnit, setQuantityUnit] = useState('Quintal');
  const [sowingDate, setSowingDate] = useState('2026-06-15');
  const [expectedHarvestDate, setExpectedHarvestDate] = useState('2026-10-20');
  const [cropStatus, setCropStatus] = useState<'Growing' | 'Ready to Harvest' | 'Stored' | 'Partially Sold' | 'Completed'>('Growing');
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const fetchCrops = async () => {
    setLoading(true);
    try {
      const endpoint = selectedStatus === 'ALL' ? '/crops' : `/crops?status=${encodeURIComponent(selectedStatus)}`;
      const list = await apiRequest<Crop[]>(endpoint);
      setCrops(list);
    } catch {
      // Fallback sample data if backend is offline
      setCrops([
        {
          id: 'crop-demo-001',
          crop_code: 'CROP-7R9K-2M4P',
          farmer_id: '00000000-0000-0000-0000-000000000001',
          farm_location: 'Lasalgaon, Nashik, Maharashtra',
          crop_name: 'Onion',
          variety: 'Nashik Red (गरवा कांदा)',
          acreage: 2.5,
          quantity: 85.0,
          quantity_unit: 'Quintal',
          sowing_date: '2026-06-15',
          expected_harvest_date: '2026-10-20',
          status: 'Growing',
          notes: 'Drip irrigated; good bulb formation.',
          aliases: { en: 'Onion', hi: 'प्याज', mr: 'कांदा' },
          created_at: '2026-06-15T10:00:00Z',
          updated_at: '2026-06-15T10:00:00Z',
        },
        {
          id: 'crop-demo-002',
          crop_code: 'CROP-3X5L-9W1Q',
          farmer_id: '00000000-0000-0000-0000-000000000001',
          farm_location: 'Lasalgaon, Nashik, Maharashtra',
          crop_name: 'Soybean',
          variety: 'JS 335 (पिवळा सोयाबीन)',
          acreage: 2.0,
          quantity: 30.0,
          quantity_unit: 'Quintal',
          sowing_date: '2026-06-20',
          expected_harvest_date: '2026-10-05',
          actual_harvest_date: '2026-10-05',
          status: 'Ready to Harvest',
          notes: 'Matured pods ready for thrashing and mandi evaluation.',
          aliases: { en: 'Soybean', hi: 'सोयाबीन', mr: 'सोयाबीन' },
          created_at: '2026-06-20T11:00:00Z',
          updated_at: '2026-10-05T09:30:00Z',
        }
      ]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCrops();
  }, [selectedStatus, profile]);

  const showNotification = (type: 'success' | 'error', message: string) => {
    setNotification({ type, message });
    setTimeout(() => setNotification(null), 4000);
  };

  const handleOpenAddModal = () => {
    setEditingCrop(null);
    setCropName('Onion');
    setVariety('Nashik Red');
    setFarmLocation(profile?.village ? `${profile.village}, ${profile.district}` : 'Lasalgaon, Nashik');
    setAcreage(2.0);
    setQuantity(60.0);
    setQuantityUnit('Quintal');
    setSowingDate('2026-06-15');
    setExpectedHarvestDate('2026-10-25');
    setCropStatus('Growing');
    setNotes('');
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (crop: Crop) => {
    setEditingCrop(crop);
    setCropName(crop.crop_name);
    setVariety(crop.variety || '');
    setFarmLocation(crop.farm_location || '');
    setAcreage(crop.acreage);
    setQuantity(crop.quantity);
    setQuantityUnit(crop.quantity_unit);
    setSowingDate(crop.sowing_date);
    setExpectedHarvestDate(crop.expected_harvest_date);
    setCropStatus(crop.status);
    setNotes(crop.notes || '');
    setIsModalOpen(true);
  };

  const handleSaveCrop = async (e: React.FormEvent) => {
    e.preventDefault();
    if (new Date(expectedHarvestDate) < new Date(sowingDate)) {
      showNotification('error', 'Expected harvest date cannot be earlier than sowing date.');
      return;
    }

    setSubmitting(true);
    try {
      if (editingCrop) {
        // Update crop
        await apiRequest(`/crops/${editingCrop.id}`, {
          method: 'PUT',
          body: JSON.stringify({
            crop_name: cropName,
            variety,
            farm_location: farmLocation,
            acreage,
            quantity,
            quantity_unit: quantityUnit,
            sowing_date: sowingDate,
            expected_harvest_date: expectedHarvestDate,
            status: cropStatus,
            notes,
          }),
        });
        showNotification('success', `Crop '${cropName}' updated successfully.`);
      } else {
        // Create new crop
        await apiRequest('/crops', {
          method: 'POST',
          body: JSON.stringify({
            crop_name: cropName,
            variety,
            farm_location: farmLocation,
            acreage,
            quantity,
            quantity_unit: quantityUnit,
            sowing_date: sowingDate,
            expected_harvest_date: expectedHarvestDate,
            status: cropStatus,
            notes,
          }),
        });
        showNotification('success', `Crop '${cropName}' created successfully.`);
      }
      setIsModalOpen(false);
      await fetchCrops();
    } catch (err: any) {
      showNotification('error', err.message || 'Operation failed');
    } finally {
      setSubmitting(false);
    }
  };

  const handleQuickStatusChange = async (cropId: string, newStatus: string) => {
    try {
      await apiRequest(`/crops/${cropId}/status?new_status=${encodeURIComponent(newStatus)}`, {
        method: 'PATCH',
      });
      showNotification('success', `Status updated to ${newStatus}`);
      await fetchCrops();
    } catch (err: any) {
      showNotification('error', err.message || 'Failed to update status');
    }
  };

  const handleDeleteCrop = async (cropId: string) => {
    try {
      await apiRequest(`/crops/${cropId}?confirmed=true`, {
        method: 'DELETE',
      });
      showNotification('success', 'Crop record deleted permanently.');
      setDeleteConfirmationId(null);
      await fetchCrops();
    } catch (err: any) {
      showNotification('error', err.message || 'Failed to delete crop');
    }
  };

  const getStatusBadgeClass = (st: string) => {
    switch (st) {
      case 'Growing':
        return 'bg-emerald-100 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-300 border-emerald-300 dark:border-emerald-800';
      case 'Ready to Harvest':
        return 'bg-amber-100 dark:bg-amber-950 text-amber-800 dark:text-amber-300 border-amber-300 dark:border-amber-800';
      case 'Stored':
        return 'bg-blue-100 dark:bg-blue-950 text-blue-800 dark:text-blue-300 border-blue-300 dark:border-blue-800';
      case 'Partially Sold':
        return 'bg-purple-100 dark:bg-purple-950 text-purple-800 dark:text-purple-300 border-purple-300 dark:border-purple-800';
      case 'Completed':
        return 'bg-stone-200 dark:bg-stone-800 text-stone-700 dark:text-stone-300 border-stone-300 dark:border-stone-700';
      default:
        return 'bg-gray-100 text-gray-700 border-gray-300';
    }
  };

  if (!user && !profile) {
    return (
      <div className="max-w-md mx-auto py-20 px-4 text-center space-y-4">
        <div className="w-16 h-16 rounded-full bg-emerald-100 dark:bg-emerald-900 text-emerald-600 dark:text-emerald-300 mx-auto flex items-center justify-center">
          <Sprout className="w-8 h-8" />
        </div>
        <h2 className="text-2xl font-bold">Farmer Access Required</h2>
        <p className="text-sm text-stone-500">
          Please sign in to view and manage your crops portfolio.
        </p>
        <button
          onClick={loginDemo}
          className="w-full py-3 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-sm shadow-md"
        >
          {t('demoSignIn')}
        </button>
      </div>
    );
  }

  const statuses = ['ALL', 'Growing', 'Ready to Harvest', 'Stored', 'Partially Sold', 'Completed'];

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center space-x-2">
            <h1 className="text-2xl sm:text-3xl font-extrabold text-stone-900 dark:text-stone-100">
              {t('myCrops')}
            </h1>
            <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-100 dark:bg-emerald-900 text-emerald-800 dark:text-emerald-200">
              {crops.length} Records
            </span>
          </div>
          <p className="text-xs text-stone-500 mt-1">
            Track cultivation lifecycle from sowing to storage and market realization
          </p>
        </div>

        <button
          onClick={handleOpenAddModal}
          className="px-5 py-3 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-sm shadow-md transition-all flex items-center justify-center space-x-2 shrink-0"
        >
          <Plus className="w-4 h-4" />
          <span>{t('addCrop')}</span>
        </button>
      </div>

      {/* Notifications Banner */}
      {notification && (
        <div className={`p-4 rounded-2xl border text-xs font-semibold flex items-center justify-between ${
          notification.type === 'success'
            ? 'bg-emerald-50 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-200 border-emerald-300 dark:border-emerald-800'
