"use client";

import React, { useState, useEffect } from 'react';
import { useLanguage } from '@/lib/language-context';
import { apiRequest } from '@/lib/api';
import {
  TrendingUp,
  Calendar,
  Layers,
  AlertTriangle,
  ShieldCheck,
  Sparkles,
  BarChart3,
  Compass,
  ArrowRight,
  Info,
  Clock,
  CheckCircle2,
  HelpCircle
} from 'lucide-react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Legend,
  AreaChart,
  Area
} from 'recharts';

interface ForecastPoint {
  horizon_days: number;
  target_date: string;
  predicted_modal_price: number;
  lower_bound: number;
  upper_bound: number;
  confidence_level: number;
  uncertainty_notes: string;
}

interface ForecastResponse {
  commodity_id: string;
  commodity_name: string;
  market_id: string;
  market_name: string;
  current_modal_price: number;
  forecasts: ForecastPoint[];
  model_version: string;
  model_algorithm: string;
  training_period: string;
  metrics: {
    mae: number;
    rmse: number;
    mape?: number;
  };
  generated_at: string;
  data_sufficiency_status: string;
  disclaimer: string;
}

export default function ForecastsPage() {
  const { language, t } = useLanguage();

  const [commodity, setCommodity] = useState<string>('c0010000-0000-0000-0000-000000000001'); // Onion
  const [market, setMarket] = useState<string>('m0010000-0000-0000-0000-000000000001'); // Lasalgaon
  const [horizon, setHorizon] = useState<number>(7);
  const [simulateInsufficient, setSimulateInsufficient] = useState<boolean>(false);

  const [forecastData, setForecastData] = useState<ForecastResponse | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const fetchForecast = async () => {
    setLoading(true);
    setErrorMessage(null);
    try {
      const res = await apiRequest<ForecastResponse>(
        `/forecasts?commodity_id=${commodity}&market_id=${market}&horizon_days=${horizon}&simulate_insufficient_data=${simulateInsufficient}`
      );
      setForecastData(res);
    } catch (err: any) {
      setErrorMessage(err.message || 'Forecast generation failed.');
      setForecastData(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchForecast();
  }, [commodity, market, horizon, simulateInsufficient]);

  const targetPoint = forecastData?.forecasts.find(p => p.horizon_days === horizon) || forecastData?.forecasts[forecastData.forecasts.length - 1];

  const currentPrice = forecastData?.current_modal_price || 2420.0;
  const predictedPrice = targetPoint?.predicted_modal_price || currentPrice;
  const changePct = (((predictedPrice - currentPrice) / currentPrice) * 100).toFixed(1);
  const isPositive = predictedPrice >= currentPrice;

  // Chart dataset
  const chartPoints = [
    {
      label: 'Today (Live)',
      price: currentPrice,
      lower: currentPrice,
      upper: currentPrice,
      horizon: 0
    },
    ...(forecastData?.forecasts.map(f => ({
      label: `+${f.horizon_days}d (${f.target_date.slice(5)})`,
      price: f.predicted_modal_price,
      lower: f.lower_bound,
      upper: f.upper_bound,
      horizon: f.horizon_days
    })) || [])
  ];

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-10">

      {/* Title Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <div className="flex items-center space-x-2">
            <h1 className="text-2xl sm:text-3xl font-extrabold text-stone-900 dark:text-stone-100">
              {t('priceForecast')} Studio
            </h1>
            <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-100 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800">
              ML Multi-Horizon
            </span>
          </div>
          <p className="text-xs text-stone-500 mt-1">
            Statistical price projections evaluated with chronological out-of-sample test splits and prediction bounds
          </p>
        </div>

        {/* Insufficient data tester toggle */}
        <label className="inline-flex items-center space-x-2 p-2 rounded-xl bg-stone-100 dark:bg-stone-800 cursor-pointer text-xs font-semibold text-stone-600 dark:text-stone-300">
          <input
            type="checkbox"
            checked={simulateInsufficient}
            onChange={(e) => setSimulateInsufficient(e.target.checked)}
            className="w-3.5 h-3.5 text-emerald-600 rounded"
          />
          <span>Simulate Insufficient Data Scenario</span>
        </label>
      </div>

      {/* Control Strip: Commodity, Mandi, and Horizon Selection */}
      <div className="p-6 rounded-3xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 shadow-sm space-y-6">

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
              Select Commodity (फसल निवडा)
            </label>
            <select
              value={commodity}
              onChange={(e) => setCommodity(e.target.value)}
              className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-xs font-bold focus:ring-2 focus:ring-emerald-500"
            >
              <option value="c0010000-0000-0000-0000-000000000001">Onion (कांदा / प्याज)</option>
              <option value="c0010000-0000-0000-0000-000000000002">Soybean (सोयाबीन)</option>
              <option value="c0010000-0000-0000-0000-000000000003">Cotton (कापूस / कपास)</option>
