                  <Area type="monotone" dataKey="upper" stroke="#93c5fd" strokeDasharray="3 3" fill="none" name="Upper 90% Bound" />
                  <Area type="monotone" dataKey="price" stroke="#059669" strokeWidth={3} fillOpacity={1} fill="url(#forecastGrad)" name="Expected Modal" />
                  <Area type="monotone" dataKey="lower" stroke="#fca5a5" strokeDasharray="3 3" fill="none" name="Lower 90% Bound" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Model Transparency & Out-of-Sample Evaluation Metrics */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

