                <div className="flex items-center justify-between py-1 border-b border-stone-200 dark:border-stone-800">
                  <span className="text-stone-500">Algorithm:</span>
                  <span className="font-semibold text-stone-800 dark:text-stone-200">{forecastData.model_algorithm}</span>
                </div>
                <div className="flex items-center justify-between py-1 border-b border-stone-200 dark:border-stone-800">
                  <span className="text-stone-500">Training Period:</span>
                  <span className="font-semibold text-stone-800 dark:text-stone-200">{forecastData.training_period}</span>
                </div>
                <div className="flex items-center justify-between py-1 border-b border-stone-200 dark:border-stone-800">
                  <span className="text-stone-500">Validation Method:</span>
                  <span className="font-semibold text-stone-800 dark:text-stone-200">Chronological Out-of-Sample (No Leakage)</span>
