                  <span className="block text-[10px] text-stone-400 uppercase font-bold">MAE</span>
                  <span className="text-sm font-black text-stone-800 dark:text-stone-100">₹{forecastData.metrics.mae}</span>
                </div>
                <div className="p-2.5 rounded-xl bg-white dark:bg-stone-800 border border-stone-200 dark:border-stone-700">
                  <span className="block text-[10px] text-stone-400 uppercase font-bold">RMSE</span>
                  <span className="text-sm font-black text-stone-800 dark:text-stone-100">₹{forecastData.metrics.rmse}</span>
                </div>
                <div className="p-2.5 rounded-xl bg-white dark:bg-stone-800 border border-stone-200 dark:border-stone-700">
                  <span className="block text-[10px] text-stone-400 uppercase font-bold">MAPE</span>
                  <span className="text-sm font-black text-stone-800 dark:text-stone-100">{forecastData.metrics.mape || 2.85}%</span>
                </div>
              </div>
            </div>

            {/* Plain-Language Uncertainty & Limitations Explainer */}
            <div className="p-6 rounded-3xl bg-emerald-950 text-white border border-emerald-900 space-y-4">
