"use client";

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/lib/auth-context';
import { useLanguage } from '@/lib/language-context';
import { apiRequest } from '@/lib/api';
import {
  MapPin,
  TrendingUp,
  Search,
  Filter,
  ShieldCheck,
  Calendar,
  Layers,
  ArrowRight,
  ArrowUpDown,
  Compass,
  AlertTriangle,
  CheckCircle2,
  Clock,
  Sparkles,
  BarChart2
} from 'lucide-react';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Legend
} from 'recharts';

interface Commodity {
  id: string;
  code: string;
  name_en: string;
  name_hi: string;
  name_mr: string;
  category: string;
  standard_unit: string;
}

interface MarketPrice {
  id: string;
  market_id: string;
  market_name: string;
  market_state: string;
  market_district: string;
  commodity_id: string;
  commodity_name: string;
  variety?: string;
  grade?: string;
  min_price: number;
  max_price: number;
  modal_price: number;
  price_unit: string;
  observation_date: string;
  source_name: string;
  is_live_api: boolean;
  data_freshness_status: 'live' | 'cached' | 'historical' | 'sample';
}

interface HistoricalPoint {
  date: string;
  modal_price: number;
  min_price: number;
  max_price: number;
  volume_arrivals_quintals: number;
  source: string;
  freshness: string;
}

interface CompareResult {
  commodity_name: string;
  best_market_by_price: string;
  cheapest_market_by_price: string;
  price_differential: number;
  markets_compared: Array<{
    market_id: string;
    market_name: string;
    district: string;
    state: string;
    distance_km?: number;
    modal_price: number;
    min_price: number;
    max_price: number;
    price_spread: number;
    freshness: string;
    observation_date: string;
    source: string;
  }>;
}

export default function MarketsPage() {
  const { profile } = useAuth();
  const { language, t } = useLanguage();

  const [commodities, setCommodities] = useState<Commodity[]>([]);
  const [selectedCommodity, setSelectedCommodity] = useState<string>('c0010000-0000-0000-0000-000000000001'); // Onion default
  const [selectedState, setSelectedState] = useState<string>('ALL');
  const [searchQuery, setSearchQuery] = useState<string>('');

  const [prices, setPrices] = useState<MarketPrice[]>([]);
  const [historyData, setHistoryData] = useState<HistoricalPoint[]>([]);
  const [historyDays, setHistoryDays] = useState<number>(30);
  const [loading, setLoading] = useState<boolean>(true);

  // Comparison selection
  const [selectedMarketsForCompare, setSelectedMarketsForCompare] = useState<string[]>([
    'm0010000-0000-0000-0000-000000000001',
    'm0010000-0000-0000-0000-000000000002'
  ]);
  const [compareData, setCompareData] = useState<CompareResult | null>(null);
  const [isComparing, setIsComparing] = useState<boolean>(false);

  // Load commodities on mount
  useEffect(() => {
    const loadCommodities = async () => {
      try {
        const commList = await apiRequest<Commodity[]>('/markets/commodities');
        setCommodities(commList);
      } catch (err) {
        console.error('Failed to load commodities:', err);
      }
    };
    loadCommodities();
  }, []);

  // Fetch prices when commodity or state changes
  useEffect(() => {
    const fetchPricesAndHistory = async () => {
      setLoading(true);
      try {
        let endpoint = `/markets/prices?commodity_id=${selectedCommodity}`;
        if (selectedState !== 'ALL') {
          endpoint += `&state=${encodeURIComponent(selectedState)}`;
        }
        const data = await apiRequest<MarketPrice[]>(endpoint);
        setPrices(data);

        // Fetch historical 30-day time-series for chart
        const hist = await apiRequest<HistoricalPoint[]>(
          `/markets/history?commodity_id=${selectedCommodity}&market_id=m0010000-0000-0000-0000-000000000001&days=${historyDays}`
        );
        setHistoryData(hist);
      } catch (err) {
        console.error('Error fetching market prices:', err);
        setPrices([]);
        setHistoryData([]);
      } finally {
        setLoading(false);
      }
    };

    fetchPricesAndHistory();
  }, [selectedCommodity, selectedState, historyDays]);

  // Handle comparison
  const handleRunComparison = async () => {
    if (selectedMarketsForCompare.length < 2) return;
    setIsComparing(true);
    try {
      const qParams = selectedMarketsForCompare.map(id => `market_ids=${encodeURIComponent(id)}`).join('&');
      const res = await apiRequest<CompareResult>(
        `/markets/compare?${qParams}&commodity_id=${selectedCommodity}&farmer_lat=20.0063&farmer_lon=74.0022`,
        { method: 'POST' }
      );
      setCompareData(res);
    } catch (e) {
      console.error('Comparison error:', e);
    } finally {
      setIsComparing(false);
    }
  };

  const toggleMarketForCompare = (marketId: string) => {
    if (selectedMarketsForCompare.includes(marketId)) {
      if (selectedMarketsForCompare.length > 2) {
        setSelectedMarketsForCompare(selectedMarketsForCompare.filter(id => id !== marketId));
      }
    } else {
      if (selectedMarketsForCompare.length < 4) {
        setSelectedMarketsForCompare([...selectedMarketsForCompare, marketId]);
      }
    }
  };

  const activeCommodity = commodities.find(c => c.id === selectedCommodity);
  const activeCropName = activeCommodity
    ? (language === 'hi' ? activeCommodity.name_hi : language === 'mr' ? activeCommodity.name_mr : activeCommodity.name_en)
    : 'Onion';

  const filteredPrices = prices.filter(p => {
    if (!searchQuery) return true;
    const q = searchQuery.toLowerCase();
    return (
      p.market_name.toLowerCase().includes(q) ||
      p.market_district.toLowerCase().includes(q) ||
      p.market_state.toLowerCase().includes(q)
    );
  });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-10">

      {/* Title & Verified Banner */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <div className="flex items-center space-x-2">
            <h1 className="text-2xl sm:text-3xl font-extrabold text-stone-900 dark:text-stone-100">
              {t('mandiPrices')} & Market Intelligence
            </h1>
            <span className="px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-100 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-200 border border-emerald-300 dark:border-emerald-800 flex items-center space-x-1">
              <ShieldCheck className="w-3.5 h-3.5 text-emerald-600" />
              <span>{t('verifiedData')}</span>
            </span>
          </div>
          <p className="text-xs text-stone-500 mt-1">
            Verified Indian APMC mandi prices with min, max, modal rates, and transit distance comparisons
          </p>
        </div>

        {/* Selected Commodity Dropdown Pill */}
        <div className="flex items-center space-x-2">
          <label className="text-xs font-bold text-stone-600 dark:text-stone-400">Crop:</label>
          <select
            value={selectedCommodity}
            onChange={(e) => setSelectedCommodity(e.target.value)}
            className="px-3.5 py-2 rounded-xl bg-white dark:bg-stone-900 border border-stone-300 dark:border-stone-700 text-stone-900 dark:text-stone-100 text-xs font-bold shadow-sm focus:ring-2 focus:ring-emerald-500"
          >
            {commodities.map((c) => {
              const label = language === 'hi' ? `${c.name_hi} (${c.name_en})` : language === 'mr' ? `${c.name_mr} (${c.name_en})` : c.name_en;
              return (
                <option key={c.id} value={c.id}>
                  {label}
                </option>
              );
            })}
          </select>
        </div>
      </div>

      {/* Filter & Search Bar */}
      <div className="p-4 rounded-2xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 shadow-sm flex flex-col sm:flex-row items-center gap-3">
        <div className="relative flex-1 w-full">
          <Search className="w-4 h-4 text-stone-400 absolute left-3 top-3" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search by mandi name, district, or market..."
            className="w-full pl-9 pr-4 py-2 rounded-xl border border-stone-200 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-xs focus:outline-none focus:ring-2 focus:ring-emerald-500"
          />
        </div>

        <div className="flex items-center space-x-2 w-full sm:w-auto">
          <Filter className="w-3.5 h-3.5 text-stone-400 shrink-0" />
          <select
            value={selectedState}
            onChange={(e) => setSelectedState(e.target.value)}
            className="px-3 py-2 rounded-xl border border-stone-200 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-xs font-semibold focus:ring-2 focus:ring-emerald-500"
          >
            <option value="ALL">All States</option>
            <option value="Maharashtra">Maharashtra</option>
            <option value="Madhya Pradesh">Madhya Pradesh</option>
            <option value="Punjab">Punjab</option>
            <option value="NCT of Delhi">NCT of Delhi</option>
          </select>
        </div>
      </div>

      {/* Live Verified Mandi Cards Grid */}
      {filteredPrices.length === 0 ? (
        <div className="p-12 text-center rounded-3xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 space-y-3">
          <AlertTriangle className="w-10 h-10 text-amber-500 mx-auto" />
          <h3 className="text-base font-bold text-stone-900 dark:text-stone-100">
            {t('noDataAvailable')}
          </h3>
          <p className="text-xs text-stone-500 max-w-md mx-auto">
            No live government observations found for {activeCropName} in the selected criteria today. We never fabricate synthetic rates. Please select "All States" or check historical records.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredPrices.map((price) => (
            <div
              key={price.id}
              className="p-6 rounded-3xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 shadow-sm hover:shadow-md transition-all flex flex-col justify-between space-y-4"
            >
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider bg-emerald-100 dark:bg-emerald-950 text-emerald-800 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-800">
                    {price.data_freshness_status === 'live' ? t('freshnessLive') : price.data_freshness_status}
                  </span>
                  <span className="text-xs text-stone-400 font-mono">
                    {price.observation_date}
                  </span>
                </div>

                <div>
                  <h3 className="text-lg font-bold text-stone-900 dark:text-stone-100">
                    {price.market_name}
                  </h3>
                  <div className="flex items-center space-x-1.5 text-xs text-stone-500 mt-0.5">
                    <MapPin className="w-3.5 h-3.5 text-emerald-600" />
                    <span>{price.market_district}, {price.market_state}</span>
                  </div>
                </div>

                <div className="p-3.5 rounded-2xl bg-stone-50 dark:bg-stone-800/60 space-y-2">
                  <div className="flex items-baseline justify-between">
                    <span className="text-xs font-semibold text-stone-500">Modal Price:</span>
                    <span className="text-2xl font-black text-emerald-700 dark:text-emerald-400">
                      ₹{price.modal_price.toLocaleString()}
                      <span className="text-xs text-stone-400 font-normal"> /Qtl</span>
                    </span>
                  </div>

                  <div className="flex items-center justify-between text-xs text-stone-500 pt-1 border-t border-stone-200 dark:border-stone-700">
                    <span>Min: ₹{price.min_price.toLocaleString()}</span>
                    <span>Max: ₹{price.max_price.toLocaleString()}</span>
                    <span>Spread: ₹{(price.max_price - price.min_price).toLocaleString()}</span>
                  </div>
                </div>
              </div>

              <div className="pt-2 flex items-center justify-between text-xs text-stone-400 border-t border-stone-100 dark:border-stone-800">
                <span className="truncate max-w-[180px]">{price.source_name}</span>
                <button
                  onClick={() => toggleMarketForCompare(price.market_id)}
                  className={`px-2.5 py-1 rounded-lg text-[11px] font-bold transition-all ${
                    selectedMarketsForCompare.includes(price.market_id)
                      ? 'bg-emerald-600 text-white'
                      : 'bg-stone-100 dark:bg-stone-800 text-stone-700 dark:text-stone-300 hover:bg-emerald-50'
                  }`}
                >
                  {selectedMarketsForCompare.includes(price.market_id) ? 'Selected' : '+ Compare'}
                </button>
              </div>

            </div>
          ))}
        </div>
      )}

      {/* Historical Price Trends Chart (Recharts) */}
      <div className="p-6 sm:p-8 rounded-3xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 shadow-sm space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <div className="flex items-center space-x-2">
              <BarChart2 className="w-5 h-5 text-emerald-600" />
              <h2 className="text-lg font-bold text-stone-900 dark:text-stone-100">
                Historical Price Trend ({activeCropName})
              </h2>
            </div>
            <p className="text-xs text-stone-500 mt-0.5">
              Verified daily modal price movement with min/max price envelope from Agmarknet
            </p>
          </div>

          <div className="flex items-center space-x-2">
            {[7, 15, 30].map((d) => (
              <button
                key={d}
                onClick={() => setHistoryDays(d)}
                className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
                  historyDays === d
                    ? 'bg-emerald-600 text-white shadow-sm'
                    : 'bg-stone-100 dark:bg-stone-800 text-stone-600 dark:text-stone-400'
                }`}
              >
                {d} Days
              </button>
            ))}
          </div>
        </div>

        {historyData.length > 0 ? (
          <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={historyData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                  <linearGradient id="modalGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.4}/>
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0.0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" className="dark:opacity-10" />
                <XAxis dataKey="date" tick={{ fontSize: 11 }} tickLine={false} />
                <YAxis tick={{ fontSize: 11 }} tickLine={false} domain={['dataMin - 100', 'dataMax + 100']} />
                <Tooltip
                  contentStyle={{
                    backgroundColor: '#1f2937',
                    borderColor: '#374151',
                    borderRadius: '12px',
                    color: '#f9fafb',
                    fontSize: '12px',
                  }}
                  formatter={(value: any) => [`₹${value}/Qtl`, '']}
                />
                <Legend wrapperStyle={{ fontSize: '11px', paddingTop: '10px' }} />
                <Area type="monotone" dataKey="max_price" stroke="#93c5fd" strokeDasharray="3 3" fill="none" name="Max Price" />
                <Area type="monotone" dataKey="modal_price" stroke="#059669" strokeWidth={3} fillOpacity={1} fill="url(#modalGradient)" name="Modal Price" />
                <Area type="monotone" dataKey="min_price" stroke="#fca5a5" strokeDasharray="3 3" fill="none" name="Min Price" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <div className="h-64 flex items-center justify-center text-xs text-stone-400">
            Historical records loading...
          </div>
        )}
      </div>

      {/* Side-by-Side Market Comparison Module */}
      <div className="p-6 sm:p-8 rounded-3xl bg-gradient-to-br from-emerald-950 via-emerald-900 to-green-950 text-white shadow-xl space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-emerald-800/80 pb-4">
          <div>
            <div className="flex items-center space-x-2">
              <Compass className="w-5 h-5 text-emerald-400" />
              <h2 className="text-lg font-bold">
                Mandi Comparison Matrix ({activeCropName})
              </h2>
            </div>
            <p className="text-xs text-emerald-300 mt-0.5">
              Compare price realizations and transit distances across up to 4 eligible APMCs
            </p>
          </div>

          <button
            onClick={handleRunComparison}
            disabled={isComparing || selectedMarketsForCompare.length < 2}
            className="px-5 py-2.5 rounded-xl bg-white text-emerald-950 hover:bg-emerald-50 font-bold text-xs shadow-md transition-all flex items-center space-x-2 shrink-0 disabled:opacity-50"
          >
            <Sparkles className="w-4 h-4 text-emerald-600" />
            <span>{isComparing ? 'Comparing...' : 'Run Side-by-Side Comparison'}</span>
          </button>
        </div>

        {compareData ? (
          <div className="space-y-4">
            <div className="flex items-center justify-between text-xs text-emerald-200">
              <div>
                Top Rate: <strong className="text-white">{compareData.best_market_by_price}</strong>
              </div>
              <div>
                Price Differential: <strong className="text-emerald-300">₹{compareData.price_differential}/Qtl</strong>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {compareData.markets_compared.map((m, idx) => (
                <div
                  key={m.market_id}
                  className={`p-5 rounded-2xl border ${
                    idx === 0
                      ? 'bg-emerald-800/80 border-emerald-400 shadow-md'
                      : 'bg-emerald-900/40 border-emerald-700/50'
                  } space-y-3`}
                >
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-mono font-bold text-emerald-300">
                      Rank #{idx + 1}
                    </span>
                    <span className="text-[10px] uppercase font-bold px-2 py-0.5 rounded bg-emerald-950 text-emerald-300">
                      {m.freshness}
                    </span>
                  </div>

                  <div>
                    <h4 className="font-bold text-sm text-white">{m.market_name}</h4>
                    <span className="text-xs text-emerald-300">{m.district}, {m.state}</span>
                  </div>

                  <div className="space-y-1">
                    <div className="text-2xl font-black text-white">
                      ₹{m.modal_price.toLocaleString()}
                      <span className="text-xs font-normal text-emerald-300"> /Qtl</span>
                    </div>
                    <div className="text-[11px] text-emerald-200">
                      Spread: ₹{m.min_price} - ₹{m.max_price}
                    </div>
                  </div>

                  {m.distance_km && (
                    <div className="flex items-center space-x-1 text-xs text-emerald-300 pt-2 border-t border-emerald-700/60">
                      <MapPin className="w-3.5 h-3.5 text-emerald-400" />
                      <span>{m.distance_km} km from Farm</span>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="text-center py-6 text-xs text-emerald-300">
            Click 'Run Side-by-Side Comparison' to evaluate prices, spreads, and distances between selected mandis.
          </div>
        )}

      </div>

    </div>
  );
}

