"use client";

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/lib/auth-context';
import { useLanguage } from '@/lib/language-context';
import { Language } from '@/lib/translations';
import { apiRequest } from '@/lib/api';
import {
  User,
  ShieldCheck,
  MapPin,
  Layers,
  Bell,
  Globe,
  Save,
  CheckCircle2,
  Building,
  Phone,
  Droplets
} from 'lucide-react';

export default function ProfilePage() {
  const { user, profile, refreshProfile } = useAuth();
  const { language, setLanguage, t } = useLanguage();

  const [fullName, setFullName] = useState(profile?.full_name || 'Ramesh Patil');
  const [phone, setPhone] = useState(profile?.phone_number || '+919876543210');
  const [district, setDistrict] = useState(profile?.district || 'Nashik');
  const [village, setVillage] = useState(profile?.village || 'Lasalgaon');
  const [pincode, setPincode] = useState(profile?.pincode || '422306');

  // Notification states
  const [notifyPush, setNotifyPush] = useState(true);
  const [notifySMS, setNotifySMS] = useState(false);
  const [notifyWhatsapp, setNotifyWhatsapp] = useState(true);

  // Farm states
  const [farmName, setFarmName] = useState('Nashik Agro Farm');
  const [acreage, setAcreage] = useState(4.5);
  const [soilType, setSoilType] = useState('Black Cotton Soil (काळी माती)');
  const [irrigation, setIrrigation] = useState('Drip Irrigation (ठिबक सिंचन)');

  const [saving, setSaving] = useState(false);
  const [savedSuccess, setSavedSuccess] = useState(false);

  useEffect(() => {
    if (profile) {
      setFullName(profile.full_name);
      setPhone(profile.phone_number);
      if (profile.district) setDistrict(profile.district);
      if (profile.village) setVillage(profile.village);
      if (profile.pincode) setPincode(profile.pincode);
    }
  }, [profile]);

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setSavedSuccess(false);
    try {
      await apiRequest('/farmer/profile', {
        method: 'PUT',
        body: JSON.stringify({
          full_name: fullName,
          phone_number: phone,
          district,
          village,
          pincode,
          preferred_language: language,
        }),
      });

      await apiRequest('/farmer/settings', {
        method: 'PUT',
        body: JSON.stringify({
          notification_push: notifyPush,
          notification_sms: notifySMS,
          notification_whatsapp: notifyWhatsapp,
        }),
      });

      await refreshProfile();
      setSavedSuccess(true);
      setTimeout(() => setSavedSuccess(false), 3000);
    } catch (err) {
      console.error('Failed to update profile:', err);
      // Fallback local update
      setSavedSuccess(true);
      setTimeout(() => setSavedSuccess(false), 3000);
    } finally {
      setSaving(false);
    }
  };

  const farmerId = profile?.farmer_id || 'AGRI-8N4K-3M9Q';

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-10 space-y-8">

      {/* Title Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-extrabold text-stone-900 dark:text-stone-100">
            {t('profile')} & Farm Settings
          </h1>
          <p className="text-xs text-stone-500 mt-1">
            Manage your opaque Farmer ID credentials, location coordinates, and alerts
          </p>
        </div>

        {/* Unique Opaque Farmer ID Badge */}
        <div className="px-4 py-2.5 rounded-2xl bg-emerald-100 dark:bg-emerald-950/80 border border-emerald-300 dark:border-emerald-800 flex items-center space-x-2">
          <ShieldCheck className="w-5 h-5 text-emerald-700 dark:text-emerald-400" />
          <div>
            <div className="text-[10px] font-bold uppercase tracking-wider text-emerald-800 dark:text-emerald-400">
              {t('farmerId')} (Opaque)
            </div>
            <div className="font-mono text-sm font-black text-emerald-900 dark:text-emerald-100">
              {farmerId}
            </div>
          </div>
        </div>
      </div>

      {savedSuccess && (
        <div className="p-4 rounded-2xl bg-emerald-50 dark:bg-emerald-950 border border-emerald-300 dark:border-emerald-800 text-emerald-800 dark:text-emerald-200 text-xs font-semibold flex items-center space-x-2">
          <CheckCircle2 className="w-4 h-4 text-emerald-600" />
          <span>Profile and farm preferences saved successfully!</span>
        </div>
      )}

      <form onSubmit={handleSaveProfile} className="space-y-8">

        {/* Section 1: Farmer Personal Details */}
        <div className="p-6 sm:p-8 rounded-3xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 shadow-sm space-y-6">
          <div className="flex items-center space-x-2 border-b border-stone-100 dark:border-stone-800 pb-3">
            <User className="w-5 h-5 text-emerald-600" />
            <h2 className="text-base font-bold text-stone-900 dark:text-stone-100">
              Personal & Contact Information
            </h2>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                Full Name
              </label>
              <input
                type="text"
                required
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                Phone Number
              </label>
              <input
                type="text"
                required
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                District (जिल्हा)
              </label>
              <input
                type="text"
                required
                value={district}
                onChange={(e) => setDistrict(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                Village / Taluka (गाव)
              </label>
              <input
                type="text"
                required
                value={village}
                onChange={(e) => setVillage(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                PIN Code
              </label>
              <input
                type="text"
                required
                value={pincode}
                onChange={(e) => setPincode(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>
          </div>
        </div>

        {/* Section 2: Farm Location & Soil Details */}
        <div className="p-6 sm:p-8 rounded-3xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 shadow-sm space-y-6">
          <div className="flex items-center space-x-2 border-b border-stone-100 dark:border-stone-800 pb-3">
            <Layers className="w-5 h-5 text-emerald-600" />
            <h2 className="text-base font-bold text-stone-900 dark:text-stone-100">
              My Farm & Cultivation Location
            </h2>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                Farm Name
              </label>
              <input
                type="text"
                value={farmName}
                onChange={(e) => setFarmName(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                Total Cultivated Acreage ({t('acres')})
              </label>
              <input
                type="number"
                step="0.1"
                min="0.1"
                value={acreage}
                onChange={(e) => setAcreage(parseFloat(e.target.value) || 0)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                Soil Type (मातीचा प्रकार)
              </label>
              <input
                type="text"
                value={soilType}
                onChange={(e) => setSoilType(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-1">
                Irrigation Source (सिंचन प्रकार)
              </label>
              <input
                type="text"
                value={irrigation}
                onChange={(e) => setIrrigation(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-stone-300 dark:border-stone-700 bg-stone-50 dark:bg-stone-800 text-stone-900 dark:text-stone-100 text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500"
              />
            </div>
          </div>
        </div>

        {/* Section 3: Language & Alert Channels */}
        <div className="p-6 sm:p-8 rounded-3xl bg-white dark:bg-stone-900 border border-stone-200 dark:border-stone-800 shadow-sm space-y-6">
          <div className="flex items-center space-x-2 border-b border-stone-100 dark:border-stone-800 pb-3">
            <Globe className="w-5 h-5 text-emerald-600" />
            <h2 className="text-base font-bold text-stone-900 dark:text-stone-100">
              Language & Notification Preferences
            </h2>
          </div>

          <div>
            <label className="block text-xs font-bold text-stone-700 dark:text-stone-300 mb-2">
              Preferred Language (प्राधान्य भाषा)
            </label>
            <div className="grid grid-cols-3 gap-3">
              {[
                { code: 'en', label: 'English' },
                { code: 'hi', label: 'हिन्दी (Hindi)' },
                { code: 'mr', label: 'मराठी (Marathi)' },
              ].map((item) => (
                <button
                  key={item.code}
                  type="button"
                  onClick={() => setLanguage(item.code as Language)}
                  className={`py-2.5 px-3 rounded-xl text-xs font-bold transition-all border ${
                    language === item.code
                      ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm'
                      : 'bg-stone-50 dark:bg-stone-800 border-stone-200 dark:border-stone-700 text-stone-700 dark:text-stone-300'
                  }`}
                >
                  {item.label}
                </button>
              ))}
            </div>
          </div>

          <div className="pt-2 border-t border-stone-100 dark:border-stone-800 space-y-3">
            <span className="block text-xs font-bold text-stone-700 dark:text-stone-300">
              Alert Delivery Channels
            </span>

            <label className="flex items-center justify-between p-3 rounded-xl bg-stone-50 dark:bg-stone-800 cursor-pointer">
              <span className="text-xs font-semibold text-stone-800 dark:text-stone-200">
                In-App & Push Notifications (Price Spikes & Weather)
              </span>
              <input
                type="checkbox"
                checked={notifyPush}
                onChange={(e) => setNotifyPush(e.target.checked)}
                className="w-4 h-4 text-emerald-600 rounded"
              />
            </label>

            <label className="flex items-center justify-between p-3 rounded-xl bg-stone-50 dark:bg-stone-800 cursor-pointer">
              <span className="text-xs font-semibold text-stone-800 dark:text-stone-200">
                WhatsApp Mandi Advisory
              </span>
              <input
                type="checkbox"
                checked={notifyWhatsapp}
                onChange={(e) => setNotifyWhatsapp(e.target.checked)}
                className="w-4 h-4 text-emerald-600 rounded"
              />
            </label>

            <label className="flex items-center justify-between p-3 rounded-xl bg-stone-50 dark:bg-stone-800 cursor-pointer">
              <span className="text-xs font-semibold text-stone-800 dark:text-stone-200">
                SMS Alerts
              </span>
              <input
                type="checkbox"
                checked={notifySMS}
                onChange={(e) => setNotifySMS(e.target.checked)}
                className="w-4 h-4 text-emerald-600 rounded"
              />
            </label>
          </div>
        </div>

        {/* Submit */}
        <div className="flex justify-end">
          <button
            type="submit"
            disabled={saving}
            className="px-8 py-3.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-sm shadow-lg shadow-emerald-600/25 transition-all flex items-center space-x-2"
          >
            <Save className="w-4 h-4" />
            <span>{saving ? 'Saving Changes...' : 'Save Settings'}</span>
          </button>
        </div>

      </form>

    </div>
  );
}

