"use client";

import React, { useState, useEffect } from 'react';
import { useAuth } from '@/lib/auth-context';
import { useLanguage } from '@/lib/language-context';
import { apiRequest } from '@/lib/api';
import {
  Compass,
  TrendingUp,
  MapPin,
  ArrowRight,
  ShieldCheck,
  AlertTriangle,
  Info,
  Truck,
  CheckCircle2,
  Clock,
  Layers,
  Sparkles,
  RefreshCw,
  IndianRupee,
  Calendar,
  Warehouse
} from 'lucide-react';

interface MandiRankingItem {
  market_id: string;
  market_name: string;
  market_district: string;
  distance_km: number;
  modal_price: number;
  gross_revenue: number;
  transport_cost: number;
  handling_cost: number;
  market_cess: number;
  net_realization: number;
  net_realization_per_quintal: number;
  rank: number;
  source: string;
}

interface RecommendationResponse {
  crop_name: string;
  quantity_quintals: number;
  recommended_action: 'SELL' | 'WAIT' | 'PARTIAL_SELL';
  confidence_pct: number;
  horizon_days: number;
  rationale_summary: string;
  detailed_factors: string[];
  recommended_mandi_id: string;
  recommended_mandi_name: string;
  expected_net_realization: number;
  expected_gross_revenue: number;
  total_logistics_deductions: number;
  net_realization_per_quintal: number;
  mandi_rankings: MandiRankingItem[];
  suggested_action_steps: string[];
  data_freshness_status: string;
}

interface CommodityOption {
  id: string;
  code: string;
  name_en: string;
  name_hi: string;
  name_mr: string;
  standard_unit: string;
}

export default function RecommendationsPage() {
  const { user } = useAuth();
  const { language, t } = useLanguage();

  const [commodities, setCommodities] = useState<CommodityOption[]>([]);
  const [selectedCommodityId, setSelectedCommodityId] = useState<string>('c0010000-0000-0000-0000-000000000001'); // Onion default
  const [quantity, setQuantity] = useState<number>(45);
  const [unit, setUnit] = useState<'QUINTAL' | 'KG' | 'TONNE'>('QUINTAL');
  const [storageDays, setStorageDays] = useState<number>(7);
  const [lat, setLat] = useState<number>(20.0063); // Nashik farm
  const [lon, setLon] = useState<number>(73.7900);

  const [loading, setLoading] = useState<boolean>(false);
  const [recommendation, setRecommendation] = useState<RecommendationResponse | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Load commodities
  useEffect(() => {
    async function loadCommodities() {
      try {
        const res = await apiRequest<CommodityOption[]>('/markets/commodities');
        setCommodities(res);
      } catch (err) {
        console.error('Error fetching commodities:', err);
      }
    }
    loadCommodities();
  }, []);

  // Fetch recommendation
  const fetchRecommendation = async () => {
    setLoading(true);
    setErrorMsg(null);
    try {
      const res = await apiRequest<RecommendationResponse>('/recommendations', {
        method: 'POST',
        body: JSON.stringify({
          commodity_id: selectedCommodityId,
          quantity: quantity,
          unit: unit,
          farmer_latitude: lat,
          farmer_longitude: lon,
          potential_storage_days: storageDays
        })
      });
      setRecommendation(res);
    } catch (err: any) {
      console.error('Recommendation fetch error:', err);
      setErrorMsg(t('noDataAvailable'));
      setRecommendation(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRecommendation();
  }, [selectedCommodityId]);

  const getCommodityName = (c: CommodityOption) => {
    if (language === 'hi') return c.name_hi;
    if (language === 'mr') return c.name_mr;
    return c.name_en;
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto space-y-8">

        {/* Page Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-200 dark:border-slate-800 pb-6">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-semibold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-300/40 mb-2">
              <Compass className="w-3.5 h-3.5" />
              <span>{t('sellingAdvisor')} • Decision Engine</span>
            </div>
            <h1 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">
              {language === 'hi' ? 'स्मार्ट बिक्री सलाहकार एवं मंडी अनुशंसा' : language === 'mr' ? 'स्मार्ट विक्री सल्लागार व बाजार शिफारस' : 'Smart Selling Advisor & Mandi Decision Engine'}
            </h1>
            <p className="mt-1 text-slate-600 dark:text-slate-4 baz400 text-sm max-w-2xl">
              {language === 'hi'
                ? 'परिवहन खर्च, मंडी शुल्क, भंडारण व्यय और आगामी मूल्य रुझान के आधार पर शुद्ध लाभ की सटीक गणना।'
                : language === 'mr'
                ? 'वाहतूक खर्च, बाजार उपकर, साठवणूक खर्च व भविष्यातील भाव कल तपासून सर्वोत्तम निव्वळ नफा ठरवा.'
                : 'Evaluates upcoming price forecasts against logistics, loading, and holding costs to maximize your Net Pocket Realization.'}
            </p>
          </div>

          <button
            onClick={fetchRecommendation}
            disabled={loading}
            className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-medium shadow-sm transition disabled:opacity-50 self-start md:self-auto cursor-pointer"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            <span>{loading ? 'Evaluating...' : 'Refresh Recommendation'}</span>
          </button>
        </div>

        {/* Input Parameters Controls */}
        <div className="bg-white dark:bg-slate-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm">
          <h2 className="text-sm font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 mb-4 flex items-center gap-2">
            <Sparkles className="w-4 h-4 text-emerald-500" />
            <span>Advisory Parameters</span>
          </h2>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {/* Commodity Selector */}
            <div>
              <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                {language === 'hi' ? 'फसल चुनें' : language === 'mr' ? 'पीक निवडा' : 'Crop / Commodity'}
              </label>
              <select
                value={selectedCommodityId}
                onChange={(e) => setSelectedCommodityId(e.target.value)}
                className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
              >
                {commodities.map((c) => (
                  <option key={c.id} value={c.id}>
                    {getCommodityName(c)} ({c.standard_unit})
                  </option>
                ))}
              </select>
            </div>

            {/* Quantity */}
            <div>
              <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                {language === 'hi' ? 'मात्रा (क्विंटल)' : language === 'mr' ? 'प्रमाण (क्विंटल)' : 'Harvest Volume (Quintals)'}
              </label>
              <input
                type="number"
                min="1"
                value={quantity}
                onChange={(e) => setQuantity(Math.max(1, parseFloat(e.target.value) || 0))}
                className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>

            {/* Potential Storage Days */}
            <div>
              <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                {language === 'hi' ? 'भंडारण अवधि (दिन)' : language === 'mr' ? 'साठवणूक कालावधी (दिवस)' : 'Potential Holding (Days)'}
              </label>
              <input
                type="number"
                min="0"
                max="60"
                value={storageDays}
                onChange={(e) => setStorageDays(Math.max(0, parseInt(e.target.value) || 0))}
                className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-sm focus:ring-2 focus:ring-emerald-500 outline-none"
              />
            </div>

            {/* Farm Location (Lat, Lon) */}
            <div>
              <label className="block text-xs font-medium text-slate-700 dark:text-slate-300 mb-1">
                {language === 'hi' ? 'खेत का स्थान' : language === 'mr' ? 'शेताचे स्थान' : 'Farm Coordinates'}
              </label>
              <div className="flex items-center gap-2">
                <input
                  type="number"
                  step="0.01"
                  value={lat}
                  onChange={(e) => setLat(parseFloat(e.target.value) || 0)}
                  className="w-1/2 px-2.5 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-xs outline-none"
                  placeholder="Lat"
                />
                <input
                  type="number"
                  step="0.01"
                  value={lon}
                  onChange={(e) => setLon(parseFloat(e.target.value) || 0)}
                  className="w-1/2 px-2.5 py-2 bg-slate-50 dark:bg-slate-800 border border-slate-300 dark:border-slate-700 rounded-xl text-slate-900 dark:text-white text-xs outline-none"
                  placeholder="Lon"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Error Fallback */}
        {errorMsg && (
          <div className="p-6 rounded-2xl bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 flex items-start gap-3 text-amber-800 dark:text-amber-200">
            <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5 text-amber-600 dark:text-amber-400" />
            <div>
              <h3 className="font-semibold text-base">{t('noDataAvailable')}</h3>
              <p className="text-sm mt-1">
                Unable to synthesize verified market pricing for this commodity. Our non-fabrication policy guarantees that market estimates are never artificially generated.
              </p>
            </div>
          </div>
        )}

        {/* Recommendation Results */}
        {recommendation && (
          <div className="space-y-8 animate-fadeIn">

            {/* Primary Action Card Banner */}
            <div className={`p-6 sm:p-8 rounded-3xl border shadow-lg transition-all ${
              recommendation.recommended_action === 'SELL'
                ? 'bg-gradient-to-br from-emerald-500/10 via-emerald-600/5 to-transparent border-emerald-500/30'
                : recommendation.recommended_action === 'WAIT'
                ? 'bg-gradient-to-br from-amber-500/10 via-amber-600/5 to-transparent border-amber-500/30'
                : 'bg-gradient-to-br from-indigo-500/10 via-indigo-600/5 to-transparent border-indigo-500/30'
            }`}>
              <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                <div>
                  <div className="flex items-center gap-3">
                    <span className={`px-4 py-1.5 rounded-full text-sm font-extrabold tracking-wide uppercase shadow-sm ${
                      recommendation.recommended_action === 'SELL'
                        ? 'bg-emerald-600 text-white'
                        : recommendation.recommended_action === 'WAIT'
                        ? 'bg-amber-500 text-slate-950'
                        : 'bg-indigo-600 text-white'
                    }`}>
                      {recommendation.recommended_action === 'SELL' ? t('sellNow') : recommendation.recommended_action === 'WAIT' ? t('wait') : t('partialSell')}
                    </span>
                    <span className="text-xs font-semibold px-2.5 py-1 rounded-md bg-slate-200/80 dark:bg-slate-800 text-slate-700 dark:text-slate-300">
                      {recommendation.confidence_pct}% Confidence Score
                    </span>
                  </div>

                  <h2 className="text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white mt-3">
                    {recommendation.rationale_summary}
                  </h2>

                  <div className="flex flex-wrap items-center gap-y-2 gap-x-6 text-sm text-slate-600 dark:text-slate-400 mt-4">
                    <div className="flex items-center gap-1.5">
                      <MapPin className="w-4 h-4 text-emerald-500" />
                      <span>Best Mandi: <strong className="text-slate-900 dark:text-white">{recommendation.recommended_mandi_name}</strong></span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <Calendar className="w-4 h-4 text-emerald-500" />
                      <span>Horizon: <strong className="text-slate-900 dark:text-white">{recommendation.horizon_days} Days</strong></span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      <Warehouse className="w-4 h-4 text-emerald-500" />
                      <span>Volume: <strong className="text-slate-900 dark:text-white">{recommendation.quantity_quintals} Quintals</strong></span>
                    </div>
                  </div>
                </div>

                {/* Big Net Realization Number */}
                <div className="bg-white/80 dark:bg-slate-900/90 backdrop-blur-md rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-md min-w-[280px] text-right">
                  <div className="text-xs uppercase font-bold text-slate-500 dark:text-slate-400 tracking-wider">
                    {t('netRealization')}
                  </div>
                  <div className="text-3xl sm:text-4xl font-extrabold text-emerald-600 dark:text-emerald-400 mt-1">
                    ₹{recommendation.expected_net_realization.toLocaleString('en-IN', { maximumFractionDigits: 0 })}
                  </div>
                  <div className="text-xs font-semibold text-slate-500 dark:text-slate-400 mt-1">
                    ₹{recommendation.net_realization_per_quintal.toFixed(1)} / Quintal (in hand)
                  </div>
                  <div className="text-[11px] text-slate-400 dark:text-slate-500 mt-2 pt-2 border-t border-slate-100 dark:border-slate-800">
                    Gross: ₹{recommendation.expected_gross_revenue.toLocaleString('en-IN')} • Deductions: ₹{recommendation.total_logistics_deductions.toLocaleString('en-IN')}
                  </div>
                </div>
              </div>

              {/* Contributing Factors */}
              <div className="mt-6 pt-6 border-t border-slate-200/60 dark:border-slate-800/60">
                <h4 className="text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 mb-3">
                  Key Economic & Agronomic Drivers:
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                  {recommendation.detailed_factors.map((factor, idx) => (
                    <div key={idx} className="flex items-start gap-2.5 text-xs text-slate-700 dark:text-slate-300 bg-white/60 dark:bg-slate-900/60 p-3 rounded-xl border border-slate-200/50 dark:border-slate-800/50">
                      <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0 mt-0.5" />
                      <span>{factor}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Mandi Net Realization Ranking Table */}
            <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
              <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                <div>
                  <h3 className="text-lg font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <MapPin className="w-5 h-5 text-emerald-500" />
                    <span>Mandi Profit Comparison Matrix</span>
                  </h3>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                    Ranked by final cash realization after geodesic freight, market fee, and labor loading
                  </p>
                </div>
                <div className="text-xs text-emerald-600 dark:text-emerald-400 font-medium px-3 py-1 rounded-full bg-emerald-50 dark:bg-emerald-950/60 border border-emerald-200 dark:border-emerald-800">
                  Freight Model: ₹0.75/km/q • Cess: 1.5% • Loading: ₹15/q
                </div>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-600 dark:text-slate-300 text-xs uppercase font-semibold border-b border-slate-200 dark:border-slate-800">
                    <tr>
                      <th className="py-3 px-4">Rank</th>
                      <th className="py-3 px-4">Mandi & District</th>
                      <th className="py-3 px-4">Distance</th>
                      <th className="py-3 px-4">Modal Price</th>
                      <th className="py-3 px-4">Gross Revenue</th>
                      <th className="py-3 px-4">Transport</th>
                      <th className="py-3 px-4">Fees & Labor</th>
                      <th className="py-3 px-4 font-bold text-emerald-600 dark:text-emerald-400">Net Realization</th>
                      <th className="py-3 px-4">Net / Quintal</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                    {recommendation.mandi_rankings.map((m) => (
                      <tr
                        key={m.market_id}
                        className={`transition hover:bg-slate-50/80 dark:hover:bg-slate-800/40 ${
                          m.rank === 1 ? 'bg-emerald-50/40 dark:bg-emerald-950/20 font-medium' : ''
                        }`}
                      >
                        <td className="py-3.5 px-4">
                          {m.rank === 1 ? (
                            <span className="inline-flex items-center justify-center w-6 h-6 rounded-full bg-emerald-600 text-white text-xs font-bold shadow-sm">
                              1
                            </span>
                          ) : (
                            <span className="text-slate-500 font-medium ml-1.5">#{m.rank}</span>
                          )}
                        </td>
                        <td className="py-3.5 px-4 font-semibold text-slate-900 dark:text-white">
                          <div className="flex items-center gap-1.5">
                            {m.market_name}
                            {m.rank === 1 && (
                              <span className="text-[10px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded bg-emerald-100 dark:bg-emerald-900 text-emerald-700 dark:text-emerald-300">
                                Best
                              </span>
                            )}
                          </div>
                          <div className="text-xs text-slate-400 font-normal">{m.market_district}</div>
                        </td>
                        <td className="py-3.5 px-4 text-slate-600 dark:text-slate-300">
                          {m.distance_km} km
                        </td>
                        <td className="py-3.5 px-4 text-slate-900 dark:text-white font-medium">
                          ₹{m.modal_price}
                        </td>
                        <td className="py-3.5 px-4 text-slate-600 dark:text-slate-300">
                          ₹{m.gross_revenue.toLocaleString('en-IN')}
                        </td>
                        <td className="py-3.5 px-4 text-rose-600 dark:text-rose-400">
                          -₹{m.transport_cost.toLocaleString('en-IN')}
                        </td>
                        <td className="py-3.5 px-4 text-slate-500 dark:text-slate-400">
                          -₹{(m.handling_cost + m.market_cess).toFixed(0)}
                        </td>
                        <td className="py-3.5 px-4 font-extrabold text-emerald-600 dark:text-emerald-400">
                          ₹{m.net_realization.toLocaleString('en-IN')}
                        </td>
                        <td className="py-3.5 px-4 font-semibold text-slate-900 dark:text-white">
                          ₹{m.net_realization_per_quintal.toFixed(1)}/q
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Actionable Steps & Dispatch Checklist */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

              {/* Checklist */}
              <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm">
                <h3 className="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2 mb-4">
                  <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                  <span>Farmer Dispatch Action Checklist</span>
                </h3>
                <div className="space-y-3">
                  {recommendation.suggested_action_steps.map((step, idx) => (
                    <div key={idx} className="flex items-start gap-3 p-3 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/60 dark:border-slate-700/60">
                      <div className="w-5 h-5 rounded-full bg-emerald-100 dark:bg-emerald-900 text-emerald-700 dark:text-emerald-300 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5">
                        {idx + 1}
                      </div>
                      <p className="text-xs font-medium text-slate-700 dark:text-slate-300 leading-relaxed">
                        {step}
                      </p>
                    </div>
                  ))}
                </div>
              </div>

              {/* Economic Disclosure & Transparency */}
              <div className="bg-white dark:bg-slate-900 rounded-3xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between">
                <div>
