                    <div className="p-3 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-100 dark:border-slate-800">
                      <strong className="text-slate-800 dark:text-slate-200">Net Realization Formula:</strong>
                      <div className="font-mono text-emerald-600 dark:text-emerald-400 mt-1">
                        Net Realization = Gross Revenue - (Transport + Market Cess + Handling + Storage/Spoilage Loss)
                      </div>
                    </div>
                    <div className="p-3 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-100 dark:border-slate-800">
                      <strong className="text-slate-800 dark:text-slate-200">Strict Non-Fabrication Guarantee:</strong>
                      <p className="mt-1">
                        When reliable APMC mandi observations are absent, prices are never synthesized. We present verified arrivals and historical trends only.
                      </p>
                    </div>
                  </div>
                </div>

                <div className="mt-6 pt-4 border-t border-slate-100 dark:border-slate-800 text-[11px] text-slate-500 flex items-center gap-1.5">
                  <Info className="w-4 h-4 shrink-0 text-slate-400" />
                  <span>{t('disclaimer')}</span>
                </div>
              </div>

            </div>

          </div>
        )}

      </div>
    </div>
  );
}

