"use client";

import React, { useState, useEffect } from 'react';
import { useLanguage } from '@/lib/language-context';
import { apiRequest } from '@/lib/api';
import {
  CloudSun,
  Sun,
  CloudRain,
  Wind,
  Droplets,
  Truck,
  ShieldAlert,
  ShieldCheck,
  AlertTriangle,
  RefreshCw,
  MapPin,
  Calendar,
  CheckCircle2,
  Info,
  Thermometer,
  Layers,
  ArrowRight,
  Bell
} from 'lucide-react';
import Link from 'next/link';

interface DailyForecast {
  date: string;
  temp_max_c: number;
  temp_min_c: number;
  precipitation_probability: number;
  condition: string;
  harvest_risk_level: 'Low' | 'Moderate' | 'High';
  transport_risk_level: 'Low' | 'Moderate' | 'High';
}

interface WeatherResponse {
  location_name: string;
  latitude: number;
  longitude: number;
  current_temperature_c: number;
  current_humidity_pct: number;
  current_precipitation_mm: number;
  wind_speed_kmh: number;
  condition: string;
  active_alerts: string[];
  forecast_days: DailyForecast[];
  source_provider: string;
  updated_at: string;
}

const LOCATION_PRESETS = [
  { name: 'Nashik, Maharashtra', lat: 20.0063, lon: 74.0022 },
  { name: 'Lasalgaon Mandi, Nashik', lat: 20.1477, lon: 74.2284 },
  { name: 'Pimpalgaon Baswant, Nashik', lat: 20.1687, lon: 73.9856 },
  { name: 'Indore, Madhya Pradesh', lat: 22.6845, lon: 75.8362 },
  { name: 'Solapur, Maharashtra', lat: 17.6599, lon: 75.9064 },
  { name: 'Akola, Maharashtra', lat: 20.7002, lon: 77.0082 },
  { name: 'Azadpur, New Delhi', lat: 28.7041, lon: 77.1725 },
];

export default function WeatherPage() {
  const { language, t } = useLanguage();

  const [selectedPreset, setSelectedPreset] = useState<string>(LOCATION_PRESETS[0].name);
  const [lat, setLat] = useState<number>(LOCATION_PRESETS[0].lat);
  const [lon, setLon] = useState<number>(LOCATION_PRESETS[0].lon);

  const [loading, setLoading] = useState<boolean>(true);
  const [weatherData, setWeatherData] = useState<WeatherResponse | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const fetchWeather = async () => {
    setLoading(true);
    setErrorMsg(null);
    try {
      const res = await apiRequest<WeatherResponse>(
        `/weather?latitude=${lat}&longitude=${lon}&location_name=${encodeURIComponent(selectedPreset)}`
      );
      setWeatherData(res);
    } catch (err: any) {
      console.error('Weather fetch error:', err);
      setErrorMsg(t('noDataAvailable'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWeather();
  }, [lat, lon]);

  const handlePresetChange = (name: string) => {
    setSelectedPreset(name);
    const found = LOCATION_PRESETS.find((p) => p.name === name);
    if (found) {
      setLat(found.lat);
      setLon(found.lon);
    }
  };

  const getRiskColor = (level: string) => {
    switch (level) {
      case 'High':
        return 'text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/60 border-rose-200 dark:border-rose-800';
      case 'Moderate':
        return 'text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-950/60 border-amber-200 dark:border-amber-800';
      default:
        return 'text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/60 border-emerald-200 dark:border-emerald-800';
    }
  };

  const currentTransitRisk = weatherData?.forecast_days?.[0]?.transport_risk_level || 'Low';

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto space-y-8">

        {/* Header */}
        <div className="border-b border-slate-200 dark:border-slate-800 pb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-semibold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-800 dark:text-emerald-300 border border-emerald-300/40 mb-2">
              <CloudSun className="w-3.5 h-3.5" />
              <span>{t('weather')} • Agro-Meteorological Intel</span>
            </div>
            <h1 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">
              {language === 'hi' ? 'कृषि मौसम एवं सड़क परिवहन जोखिम' : language === 'mr' ? 'शेती हवामान व वाहतूक जोखीम' : 'Agro Weather & Produce Transit Risk'}
            </h1>
            <p className="mt-1 text-slate-600 dark:text-slate-400 text-sm max-w-2xl">
              {language === 'hi'
                ? 'सरकारी एवं मौसम विज्ञान डेटा के आधार पर वर्षा, आर्द्रता व मंडी परिवहन की सुरक्षा संबंधी दिशा-निर्देश।'
                : language === 'mr'
                ? 'पाऊस, आर्द्रता व वाऱ्याच्या वेगावरून शेतमाल वाहतूक आणि काढणीच्या सुरक्षित वेळेचे नियोजन करा.'
                : 'Real-time meteorological monitoring and transit advisories tailored for perishables heading to APMC mandis.'}
            </p>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={fetchWeather}
              disabled={loading}
              className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-medium shadow-sm transition disabled:opacity-50 cursor-pointer text-sm"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
              <span>Refresh Forecast</span>
            </button>
          </div>
        </div>

        {/* Location Selector Bar */}
        <div className="bg-white dark:bg-slate-900 rounded-2xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <MapPin className="w-5 h-5 text-emerald-600 dark:text-emerald-400 shrink-0" />
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Observatory Location
              </label>
              <select
                value={selectedPreset}
                onChange={(e) => handlePresetChange(e.target.value)}
                className="mt-1 font-semibold text-slate-900 dark:text-white bg-transparent border-b border-emerald-500 focus:outline-none cursor-pointer text-sm"
              >
                {LOCATION_PRESETS.map((p) => (
                  <option key={p.name} value={p.name} className="dark:bg-slate-900">
                    {p.name} ({p.lat.toFixed(2)}°N, {p.lon.toFixed(2)}°E)
                  </option>
                ))}
              </select>
            </div>
          </div>

          {weatherData && (
            <div className="text-xs text-slate-500 dark:text-slate-400 flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
              <span>{weatherData.source_provider}</span>
            </div>
          )}
        </div>

        {/* Error Fallback */}
        {errorMsg && (
          <div className="p-6 rounded-2xl bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 flex items-start gap-3 text-amber-800 dark:text-amber-200">
            <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" />
            <div>
              <h3 className="font-semibold text-base">{t('noDataAvailable')}</h3>
              <p className="text-sm mt-1">
                Unable to reach real-time weather feed. Please verify network connectivity.
              </p>
            </div>
          </div>
        )}

        {/* Weather Content */}
        {weatherData && (
          <div className="space-y-8 animate-fadeIn">

            {/* Top Grid: Hero Weather Card (7 cols) + Transit Risk Advisory (5 cols) */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

              {/* Current Weather Card */}
              <div className="lg:col-span-7 bg-gradient-to-br from-emerald-700 via-emerald-800 to-green-900 rounded-3xl p-6 sm:p-8 text-white shadow-xl flex flex-col justify-between">
                <div>
                  <div className="flex items-center justify-between">
                    <span className="text-emerald-200 text-xs font-semibold uppercase tracking-wider">
                      Current Agro-Climate Observation
                    </span>
                    <span className="text-xs px-2.5 py-1 rounded-full bg-white/20 backdrop-blur-sm text-white font-medium">
                      {weatherData.condition}
                    </span>
                  </div>

                  <div className="mt-4 flex items-baseline gap-4">
                    <span className="text-5xl sm:text-6xl font-extrabold tracking-tight">
                      {weatherData.current_temperature_c.toFixed(1)}°C
                    </span>
                    <span className="text-emerald-200 text-lg">
                      {weatherData.condition}
                    </span>
                  </div>
                </div>

                {/* 4 Sensor Metrics */}
                <div className="mt-8 pt-6 border-t border-emerald-600/60 grid grid-cols-3 sm:grid-cols-4 gap-4">
                  <div className="bg-white/10 rounded-2xl p-3 text-center">
                    <Droplets className="w-4 h-4 mx-auto text-emerald-200 mb-1" />
                    <div className="text-[11px] text-emerald-200">Humidity</div>
                    <div className="text-base font-bold mt-0.5">{weatherData.current_humidity_pct}%</div>
                  </div>

                  <div className="bg-white/10 rounded-2xl p-3 text-center">
                    <CloudRain className="w-4 h-4 mx-auto text-emerald-200 mb-1" />
                    <div className="text-[11px] text-emerald-200">Rainfall</div>
                    <div className="text-base font-bold mt-0.5">{weatherData.current_precipitation_mm} mm</div>
                  </div>

                  <div className="bg-white/10 rounded-2xl p-3 text-center">
                    <Wind className="w-4 h-4 mx-auto text-emerald-200 mb-1" />
                    <div className="text-[11px] text-emerald-200">Wind Speed</div>
                    <div className="text-base font-bold mt-0.5">{weatherData.wind_speed_kmh} km/h</div>
                  </div>

                  <div className="hidden sm:block bg-white/10 rounded-2xl p-3 text-center">
                    <Sun className="w-4 h-4 mx-auto text-emerald-200 mb-1" />
                    <div className="text-[11px] text-emerald-200">Precip Prob.</div>
                    <div className="text-base font-bold mt-0.5">
                      {weatherData.forecast_days[0]?.precipitation_probability || 0}%
                    </div>
                  </div>
                </div>
              </div>

              {/* Transit Risk & Advisory Card */}
              <div className="lg:col-span-5 bg-white dark:bg-slate-900 rounded-3xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between">
                <div>
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">
                      <Truck className="w-5 h-5 text-emerald-500" />
                      <span>Produce Transit Advisory</span>
                    </h3>
                    <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase border ${getRiskColor(currentTransitRisk)}`}>
                      {currentTransitRisk} Transit Risk
                    </span>
                  </div>

                  <div className="space-y-3.5 text-xs text-slate-600 dark:text-slate-300">
                    {currentTransitRisk === 'High' ? (
                      <div className="p-4 rounded-2xl bg-rose-50 dark:bg-rose-950/40 border border-rose-200 dark:border-rose-800 text-rose-800 dark:text-rose-200 space-y-1">
                        <strong className="block font-bold">Severe Moisture / Transit Hazard</strong>
                        <p>Rain or high winds exceed safe open transport thresholds. Perishables like onions and tomatoes face severe spoilage risks without heavy double-layer tarpaulins.</p>
                      </div>
                    ) : currentTransitRisk === 'Moderate' ? (
                      <div className="p-4 rounded-2xl bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800 text-amber-800 dark:text-amber-200 space-y-1">
                        <strong className="block font-bold">Precautionary Tarpaulin Cover Advised</strong>
                        <p>Scattered rainfall expected along transit corridors. Ensure all bags/crates on transport trucks are secured with waterproof sheeting before leaving the farm gate.</p>
                      </div>
                    ) : (
                      <div className="p-4 rounded-2xl bg-emerald-50 dark:bg-emerald-950/40 border border-emerald-200 dark:border-emerald-800 text-emerald-800 dark:text-emerald-200 space-y-1">
                        <strong className="block font-bold">Ideal Mandi Dispatch Road Conditions</strong>
                        <p>Dry highways, low precipitation probability, and mild winds. Produce will reach APMC yards in prime condition without moisture degradation.</p>
                      </div>
                    )}

                    <div className="pt-2 space-y-2">
                      <div className="flex items-center gap-2">
                        <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
                        <span>Recommended departure: <strong>Early Morning (4:00 AM – 7:00 AM)</strong></span>
                      </div>
                      <div className="flex items-center gap-2">
                        <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
                        <span>Max recommended haul distance: <strong>120 km</strong></span>
                      </div>
                    </div>
                  </div>
                </div>

                <div className="mt-6 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between">
                  <Link
                    href="/recommendations"
                    className="inline-flex items-center gap-1.5 text-xs font-semibold text-emerald-600 dark:text-emerald-400 hover:underline"
                  >
                    <span>Check Selling Decision</span>
                    <ArrowRight className="w-3.5 h-3.5" />
                  </Link>

                  <Link
                    href="/dashboard"
                    className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-slate-800 dark:hover:text-slate-200"
                  >
                    <Bell className="w-3.5 h-3.5" />
                    <span>View Alerts</span>
                  </Link>
                </div>
              </div>

            </div>

            {/* 7-Day Forecast Matrix */}
            <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm p-6 sm:p-8 space-y-6">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-100 dark:border-slate-800 pb-4">
                <div>
                  <h3 className="text-lg font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <Calendar className="w-5 h-5 text-emerald-500" />
                    <span>7-Day Agricultural Harvest & Transit Outlook</span>
                  </h3>
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                    Plan harvesting dates and market transport based on anticipated precipitation
                  </p>
                </div>
                <div className="text-xs font-medium text-slate-500">
                  Updated every 6 hours from satellite & surface stations
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-3">
                {weatherData.forecast_days.map((day, idx) => {
                  const dObj = new Date(day.date);
                  const dayName = dObj.toLocaleDateString('en-US', { weekday: 'short' });
                  const dateStr = dObj.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

                  return (
                    <div
                      key={day.date}
                      className={`p-4 rounded-2xl border transition-all hover:scale-[1.02] flex flex-col justify-between ${
                        idx === 0
                          ? 'bg-emerald-50/50 dark:bg-emerald-950/20 border-emerald-300 dark:border-emerald-700'
                          : 'bg-slate-50/60 dark:bg-slate-800/40 border-slate-200/80 dark:border-slate-700/80'
                      }`}
                    >
                      <div>
                        <div className="flex items-center justify-between">
                          <span className="font-bold text-sm text-slate-900 dark:text-white">
                            {idx === 0 ? 'Today' : dayName}
                          </span>
                          <span className="text-[10px] text-slate-400">{dateStr}</span>
                        </div>

                        <div className="mt-3 text-center">
                          {day.precipitation_probability > 30 ? (
                            <CloudRain className="w-8 h-8 mx-auto text-blue-500" />
                          ) : (
                            <Sun className="w-8 h-8 mx-auto text-amber-500" />
                          )}
                          <div className="text-xs font-semibold text-slate-800 dark:text-slate-200 mt-2 truncate" title={day.condition}>
                            {day.condition}
                          </div>
                          <div className="text-sm font-bold mt-1 text-slate-900 dark:text-white">
                            {day.temp_max_c.toFixed(0)}° / <span className="text-slate-400 font-normal">{day.temp_min_c.toFixed(0)}°C</span>
                          </div>
                        </div>
                      </div>

                      <div className="mt-4 pt-3 border-t border-slate-200/60 dark:border-slate-700/60 space-y-1.5 text-[11px]">
                        <div className="flex justify-between items-center">
                          <span className="text-slate-400">Rain Prob:</span>
                          <span className="font-semibold text-slate-700 dark:text-slate-300">{day.precipitation_probability}%</span>
                        </div>
                        <div className="flex justify-between items-center">
                          <span className="text-slate-400">Transit:</span>
                          <span className={`px-1.5 py-0.2 rounded font-bold uppercase text-[9px] ${
                            day.transport_risk_level === 'High' ? 'text-rose-600' : day.transport_risk_level === 'Moderate' ? 'text-amber-600' : 'text-emerald-600'
                          }`}>
                            {day.transport_risk_level}
                          </span>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

          </div>
        )}

      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useAuth } from '@/lib/auth-context';
import { useLanguage } from '@/lib/language-context';
import { useTheme } from '@/lib/theme-context';
import { Language } from '@/lib/translations';
import { apiRequest } from '@/lib/api';
import {
  Sprout,
  Sun,
  Moon,
  Globe,
  Bell,
  Menu,
  X,
  User,
  LogOut,
  TrendingUp,
  MapPin,
  Calculator,
  Compass,
  LayoutDashboard,
  CloudSun,
  Check
} from 'lucide-react';

export const Navbar: React.FC = () => {
  const pathname = usePathname();
  const { user, profile, logout } = useAuth();
  const { language, setLanguage, t } = useLanguage();
  const { theme, toggleTheme } = useTheme();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [langMenuOpen, setLangMenuOpen] = useState(false);
  const [notifMenuOpen, setNotifMenuOpen] = useState(false);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [unreadCount, setUnreadCount] = useState<number>(2);

  const navLinks = [
    { href: '/dashboard', label: t('dashboard'), icon: LayoutDashboard },
    { href: '/crops', label: t('myCrops'), icon: Sprout },
    { href: '/markets', label: t('mandiPrices'), icon: MapPin },
    { href: '/forecasts', label: t('priceForecast'), icon: TrendingUp },
    { href: '/recommendations', label: t('sellingAdvisor'), icon: Compass },
    { href: '/calculator', label: t('calculator'), icon: Calculator },
    { href: '/weather', label: t('weather'), icon: CloudSun },
  ];

  useEffect(() => {
    async function loadNotifications() {
      try {
        const res = await apiRequest<any[]>('/notifications');
        if (Array.isArray(res)) {
          setNotifications(res);
          setUnreadCount(res.filter((n) => !n.is_read).length);
        }
      } catch (err) {
        setNotifications([
          {
            id: 'notif-001',
            title_en: 'Onion Price Spike in Pimpalgaon Mandi',
            title_hi: 'पिंपलगांव मंडी में प्याज के भाव में तेजी',
            title_mr: 'पिंपळगाव बाजार समितीत कांद्याच्या दरात वाढ',
            message_en: 'Modal price reached ₹2,480/Quintal (+4.2% change today).',
            is_read: false,
          },
          {
            id: 'notif-003',
            title_en: 'Transit Weather Notice: Light Rain Expected',
            title_hi: 'परिवहन मौसम सूचना: हल्की बारिश की संभावना',
            title_mr: 'वाहतूक हवामान सूचना: हलक्या पावसाची शक्यता',
            message_en: 'Tarpaulin cover advised for produce in transit across Nashik route.',
            is_read: false,
          }
        ]);
        setUnreadCount(2);
      }
    }
    loadNotifications();
  }, []);

  const markAsRead = async (id: string) => {
    try {
      await apiRequest(`/notifications/${id}/read`, { method: 'PATCH' });
    } catch (e) {
      // client-side update
    }
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, is_read: true } : n))
    );
    setUnreadCount((prev) => Math.max(0, prev - 1));
  };

  const handleLanguageChange = (lang: Language) => {
    setLanguage(lang);
    setLangMenuOpen(false);
  };

  return (
    <header className="sticky top-0 z-50 bg-white/95 dark:bg-emerald-950/95 backdrop-blur-md border-b border-emerald-100 dark:border-emerald-900 transition-colors">
