"use client";

import React, { createContext, useContext, useEffect, useState } from 'react';
import { supabase, isSupabaseConfigured } from './supabase';
import { apiRequest } from './api';

export interface FarmerProfile {
  id: string;
  farmer_id: string;
  full_name: string;
  phone_number: string;
  preferred_language: 'en' | 'hi' | 'mr';
  state?: string;
  district?: string;
  sub_district?: string;
  village?: string;
  pincode?: string;
  created_at: string;
  updated_at: string;
}

interface AuthContextType {
  user: any | null;
  profile: FarmerProfile | null;
  token: string | null;
  loading: boolean;
  login: (emailOrPhone: string, password?: string) => Promise<void>;
  loginDemo: () => Promise<void>;
  register: (name: string, phone: string, district: string, village: string) => Promise<void>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

function createDemoJwt(userId = '00000000-0000-0000-0000-000000000001', email = 'ramesh.patil@kisan.in'): string {
  try {
    const header = typeof btoa !== 'undefined' ? btoa(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).replace(/=+$/, '') : 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9';
    const payload = typeof btoa !== 'undefined' ? btoa(JSON.stringify({
      sub: userId,
      email: email,
      role: 'authenticated',
      aud: 'authenticated',
      exp: Math.floor(Date.now() / 1000) + 31536000,
    })).replace(/=+$/, '') : 'eyJzdWIiOiIwMDAwMDAwMC0wMDAwLTAwMDAtMDAwMC0wMDAwMDAwMDAwMDEifQ';
    return `${header}.${payload}.demo_sig`;
  } catch {
    return 'demo-jwt-token-farmer-nashik';
  }
}

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<any | null>(null);
  const [profile, setProfile] = useState<FarmerProfile | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

  // Initialize session on mount
  useEffect(() => {
    const initAuth = async () => {
      try {
        let savedToken = localStorage.getItem('krishi_auth_token');
        const savedUserStr = localStorage.getItem('krishi_auth_user');

        // Auto-heal legacy unformatted demo tokens
        if (savedToken && !savedToken.includes('.')) {
          savedToken = createDemoJwt();
          localStorage.setItem('krishi_auth_token', savedToken);
        }

        if (savedToken && savedUserStr) {
          const parsedUser = JSON.parse(savedUserStr);
          setUser(parsedUser);
          setToken(savedToken);
          try {
            const p = await apiRequest<FarmerProfile>('/farmer/profile', {}, savedToken);
            setProfile(p);
          } catch {
            // Profile fetch fallback for demo mode
            setProfile({
              id: parsedUser.id,
              farmer_id: 'AGRI-9M2K-7P4W',
              full_name: parsedUser.email?.split('@')[0] || 'Ramesh Patil',
              phone_number: '+919876543210',
              preferred_language: 'en',
              state: 'Maharashtra',
              district: 'Nashik',
              village: 'Lasalgaon',
              pincode: '422306',
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString(),
            });
          }
        }
      } catch (err) {
        console.error('Failed to restore session:', err);
      } finally {
        setLoading(false);
      }
    };

    initAuth();
  }, []);

  const refreshProfile = async () => {
    if (!token) return;
    try {
      const p = await apiRequest<FarmerProfile>('/farmer/profile', {}, token);
      setProfile(p);
    } catch (e) {
      console.error('Error refreshing profile:', e);
    }
  };

  const loginDemo = async () => {
    setLoading(true);
    try {
      // Demo farmer credentials
      const demoToken = createDemoJwt();
      const demoUser = {
        id: '00000000-0000-0000-0000-000000000001',
        email: 'ramesh.patil@kisan.in',
      };
      localStorage.setItem('krishi_auth_token', demoToken);
      localStorage.setItem('krishi_auth_user', JSON.stringify(demoUser));
      setUser(demoUser);
      setToken(demoToken);

      try {
        const p = await apiRequest<FarmerProfile>('/farmer/profile', {}, demoToken);
        setProfile(p);
      } catch {
        setProfile({
          id: demoUser.id,
          farmer_id: 'AGRI-8N4K-3M9Q',
          full_name: 'Ramesh Patil',
          phone_number: '+919876543210',
          preferred_language: 'mr',
          state: 'Maharashtra',
          district: 'Nashik',
          village: 'Lasalgaon',
          pincode: '422306',
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        });
      }
    } finally {
      setLoading(false);
    }
  };

  const login = async (emailOrPhone: string, password = 'password123') => {
    setLoading(true);
    try {
      if (isSupabaseConfigured) {
        const { data, error } = await supabase.auth.signInWithPassword({
          email: emailOrPhone.includes('@') ? emailOrPhone : `${emailOrPhone}@kisan.in`,
          password,
        });
        if (error) throw error;
        if (data.session) {
          const t = data.session.access_token;
          localStorage.setItem('krishi_auth_token', t);
          localStorage.setItem('krishi_auth_user', JSON.stringify(data.user));
          setUser(data.user);
          setToken(t);
          await refreshProfile();
        }
      } else {
        // Fallback demo login
        await loginDemo();
      }
    } finally {
      setLoading(false);
    }
  };

  const register = async (name: string, phone: string, district: string, village: string) => {
    setLoading(true);
    try {
      const dummyUser = {
        id: `user-${Date.now().toString(36)}`,
        email: `${phone}@kisan.in`,
      };
      const demoToken = createDemoJwt(dummyUser.id, dummyUser.email);
      localStorage.setItem('krishi_auth_token', demoToken);
      localStorage.setItem('krishi_auth_user', JSON.stringify(dummyUser));
      setUser(dummyUser);
      setToken(demoToken);

      const newProfile: FarmerProfile = {
        id: dummyUser.id,
        farmer_id: `AGRI-${Math.random().toString(36).substring(2, 6).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`,
        full_name: name,
        phone_number: phone,
        preferred_language: 'en',
        state: 'Maharashtra',
        district,
        village,
        pincode: '422306',
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };
      setProfile(newProfile);
    } finally {
      setLoading(false);
    }
  };

  const logout = async () => {
    localStorage.removeItem('krishi_auth_token');
    localStorage.removeItem('krishi_auth_user');
    setUser(null);
    setProfile(null);
    setToken(null);
    if (isSupabaseConfigured) {
      await supabase.auth.signOut();
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        profile,
        token,
        loading,
        login,
        loginDemo,
        register,
        logout,
        refreshProfile,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

